    /*
     * The API lives beside the page on the same machine, one port over. Using
     * a literal `localhost` meant a page opened on a phone called the PHONE's
     * own localhost, failed every request, and surfaced as "Backend offline" —
     * indistinguishable from a dead server. Following the host we were served
     * from is correct on the laptop (localhost -> localhost) and correct on a
     * phone with nothing to configure. An explicit override still wins.
     */
    /**
     * Where the API lives, when nobody has said.
     *
     * Follow the host that served the page — correct on the laptop
     * (localhost -> localhost) and correct on a phone browsing the LAN, with
     * nothing to configure.
     *
     * Except when there is no host to follow. The iOS app loads this file from
     * its own bundle, where the protocol is file: and the hostname is empty,
     * and the earlier expression produced "file://localhost:3100" — a scheme
     * that reaches nothing and surfaces as "Backend offline", the same
     * misdiagnosis an oversize upload once produced. There the answer is
     * genuinely unknown: the API runs on a Mac somewhere else, so the app asks
     * and stores it as `film_api_url`.
     *
     * A named function rather than an inline expression so it can be read and
     * evaluated by a test without guessing where the statement ends.
     */
    function defaultApiBase(loc) {
        const l = loc || {};
        if (!/^https?:$/.test(String(l.protocol || ''))) return '';
        return l.protocol + '//' + (l.hostname || 'localhost') + ':3100';
    }

    /* ── WEB STORAGE THAT CANNOT TAKE THE PAGE DOWN ─────────────────────────
     *
     * localStorage does not merely return null when it is unavailable — the
     * ACCESSOR THROWS. A private window, a browser set to block site data, and
     * an opaque or restricted origin all raise `SecurityError: The operation is
     * insecure.` on the first touch.
     *
     * `let API_BASE = localStorage.getItem(...)` sat at the top level of this
     * script, unguarded, so a throw there killed EVERYTHING BELOW IT: no
     * function after this line was ever defined, so no request was made and
     * every onclick in the markup named something that did not exist. The app
     * painted its shell and responded to nothing — indistinguishable from a
     * dead server, which is where it sent everybody looking.
     *
     * A helper rather than a try at each site, because a try can be forgotten
     * and a helper cannot: seven sites were bare when this was written.
     */
    const feStore = (() => {
        const ok = (fn, fallback) => { try { return fn(); } catch (_) { return fallback; } };
        return {
            get: (k) => ok(() => localStorage.getItem(k), null),
            set: (k, v) => ok(() => { localStorage.setItem(k, v); return true; }, false),
            remove: (k) => ok(() => { localStorage.removeItem(k); return true; }, false),
        };
    })();

