    function updateSceneNumbers() {
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;

        const sceneHeadings = editor.querySelectorAll('[data-element-type="scene-heading"]');
        let autoNum = 0;

        sceneHeadings.forEach(heading => {
            autoNum++;

            if (!sceneNumbersLocked) {
                // When unlocked, auto-calculate sequential numbers
                heading.dataset.sceneNumber = String(autoNum);
            }
            // When locked, preserve existing data-scene-number attributes

            // Update the gutter display
            updateSceneGutter(heading);
        });
    }

    function updateSceneGutter(heading) {
        // Remove existing gutter span if any
        let gutter = heading.querySelector('.scene-number-gutter');
        if (!gutter) {
            gutter = document.createElement('span');
            gutter.className = 'scene-number-gutter';
            gutter.contentEditable = 'false';
            heading.insertBefore(gutter, heading.firstChild);

            // Double-click to edit scene number
            gutter.addEventListener('dblclick', (e) => {
                e.preventDefault();
                e.stopPropagation();
                startEditSceneNumber(heading, gutter);
            });
        }

        const sceneNum = heading.dataset.sceneNumber || '';
        gutter.textContent = sceneNum;
        gutter.classList.toggle('locked', sceneNumbersLocked);
    }

    function updateSceneNumberGutters() {
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;

        const sceneHeadings = editor.querySelectorAll('[data-element-type="scene-heading"]');
        sceneHeadings.forEach(heading => {
            updateSceneGutter(heading);
        });
    }

    function startEditSceneNumber(heading, gutter) {
        // Make gutter editable
        gutter.classList.add('editing');
        gutter.contentEditable = 'true';
        gutter.focus();

        // Select all text
        const range = document.createRange();
        range.selectNodeContents(gutter);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);

        // Handle blur to save
        const finishEdit = () => {
            const newNum = gutter.textContent.trim();
            if (newNum) {
                heading.dataset.sceneNumber = newNum;
                // Lock numbers when manually edited
                if (!sceneNumbersLocked) {
                    toggleLockSceneNumbers();
                }
            }
            gutter.contentEditable = 'false';
            gutter.classList.remove('editing');
            gutter.classList.toggle('locked', sceneNumbersLocked);
            gutter.removeEventListener('blur', finishEdit);
            gutter.removeEventListener('keydown', handleEditKey);
        };

        const handleEditKey = (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                gutter.blur();
            } else if (e.key === 'Escape') {
                // Restore original
                gutter.textContent = heading.dataset.sceneNumber || '';
                gutter.blur();
            }
        };

        gutter.addEventListener('blur', finishEdit);
        gutter.addEventListener('keydown', handleEditKey);
    }

    // ── AI Chat: streaming send ────────────────────────────────────


    // ── Which path an AI request takes ─────────────────────────────────────
    //
    // The goal's stated rabbit hole: use MCP wherever we can for AI queries. The
    // MCP surface has always been protected by a test that forbids any tool from
    // calling a server-side LLM — but that said nothing about this panel, which
    // is the surface actually typed into. Option (c): MCP is the default when a
    // host is attached, these routes are the fallback, and the writer is told
    // which is which instead of finding out on a bill.

    const AI_PATH = { connected: false, checked: 0 };

    async function saveScreenplay() {
        if (!state.currentProject) return;
        const editor = document.getElementById('screenplayEditor');

        // Convert editor content back to Fountain
        const fountainText = serializeEditorToFountain(editor);
        if (!fountainText.trim()) {
            setStatus('Nothing to save');
            return;
        }

        updateSaveStatus('saving');
        setStatus('Saving...');
        try {
            // FILM-129: Check if this should be marked as a revision
            const markAsRevision = getMarkAsRevision();
            const requestBody = { fountain_content: fountainText };
            if (markAsRevision) {
                requestBody.mark_as_revision = true;
            }

            const data = await api('/projects/' + state.currentProject.id + '/script', {
                method: 'POST', body: JSON.stringify(requestBody)
            });

            // FILM-129: Update revision info
            loadRevisionInfo(data.script);

            // Reset the mark as revision checkbox after saving
            const checkbox = document.getElementById('markAsRevisionCheckbox');
            if (checkbox) checkbox.checked = false;

            setStatus(`Saved as v${data.script.version}${markAsRevision ? ' (Revision)' : ''}`);
            editorDirty = false;
            currentFountainContent = fountainText;
            currentScriptVersion = data.script.version; // FILM-104: Track version for auto-save
            updateSaveStatus('saved');
            loadScriptVersions();
            // FILM-121: Check for new entity suggestions
            checkScreenplaySuggestions();
        } catch (err) {
            setStatus('Error: ' + err.message);
            updateSaveStatus('unsaved');
        }
    }

    // FILM-104: Serialize editor content to Fountain format with inline formatting
    function editorToFountain(editor) {
        return serializeEditorToFountain(editor);
    }

    function serializeEditorToFountain(editor) {
        // Convert editor HTML back to Fountain text
        // Handles data-element-type and inline formatting (bold, italic, underline)

        const lines = [];
        let prevType = null;

        // FILM-128: Handle title page block at the start
        const titlePageBlock = editor.querySelector('[data-element-type="title-page"]');
        if (titlePageBlock && titlePageBlock.dataset.titlePageData) {
            try {
                const titlePage = JSON.parse(titlePageBlock.dataset.titlePageData);
                const titlePageFountain = serializeTitlePageToFountain(titlePage);
                if (titlePageFountain) {
                    lines.push(titlePageFountain.trim());
                }
            } catch (e) {
                console.error('Failed to serialize title page:', e);
            }
        }

        // FILM-109: Helper to serialize a single element
        function serializeElement(el, isRightDualChar = false) {
            const text = extractFormattedText(el).trim();
            let elementType = el.dataset && el.dataset.elementType;
            if (!elementType) {
                const classes = [...el.classList];
                const spClass = classes.find(c => c.startsWith('sp-'));
                elementType = spClass ? spClass.replace('sp-', '') : 'action';
            }

            if (!text) return;

            switch (elementType) {
                case 'scene-heading': {
                    // The heading is styled bold by CSS; any bold run inside it
                    // would come back as ** and be shown literally next reload.
                    const headingText = stripEmphasisMarkers(text);
                    const hasPrefix = /^(INT|EXT|EST|INT\.?\/?EXT|I\/E)[\.\s]/i.test(headingText);
                    let headingLine = hasPrefix ? headingText.toUpperCase() : '.' + headingText.toUpperCase();
                    const sceneNumber = el.dataset && el.dataset.sceneNumber;
                    if (sceneNumber) {
                        headingLine += ' #' + sceneNumber + '#';
                    }
                    lines.push('', headingLine);
                    break;
                }
                case 'character':
                    // FILM-109: Add ^ suffix for right-side dual dialogue character
                    if (isRightDualChar || el.dataset.dualRight) {
                        lines.push('', text.toUpperCase() + ' ^');
                    } else {
                        lines.push('', text.toUpperCase());
                    }
                    break;
                case 'dialogue':
                    lines.push(text);
                    break;
                case 'parenthetical':
                    if (!text.startsWith('(')) {
                        lines.push('(' + text + ')');
                    } else {
                        lines.push(text);
                    }
                    break;
                case 'transition':
                    if (text.endsWith(':')) {
                        lines.push('', text.toUpperCase());
                    } else {
                        lines.push('', '> ' + text.toUpperCase());
                    }
                    break;
                case 'centered':
                    lines.push('', '> ' + text + ' <');
                    break;
                case 'lyrics':
                    lines.push('~' + text);
                    break;
                case 'note':
                    lines.push('[[' + text + ']]');
                    break;
                case 'dual-dialogue':
                    lines.push('', text.toUpperCase() + ' ^');
                    break;
                case 'action':
                default:
                    if (prevType !== 'action' && prevType !== null) {
                        lines.push('');
                    }
                    lines.push(text);
                    break;
            }
            prevType = elementType;
        }

        // Walk through direct children of editor
        for (const child of editor.children) {
            // FILM-109: Handle dual dialogue containers
            if (child.classList.contains('dual-dialogue-container')) {
                const leftCol = child.querySelector('.dual-dialogue-column.left');
                const rightCol = child.querySelector('.dual-dialogue-column.right');

                // Serialize left column first
                if (leftCol) {
                    const leftEls = leftCol.querySelectorAll('[data-element-type]');
                    leftEls.forEach(el => serializeElement(el, false));
                }

                // Serialize right column (first character gets ^ suffix)
                if (rightCol) {
                    const rightEls = Array.from(rightCol.querySelectorAll('[data-element-type]'));
                    rightEls.forEach((el, i) => {
                        const isFirstChar = i === 0 && el.dataset.elementType === 'character';
                        serializeElement(el, isFirstChar);
                    });
                }
                continue;
            }

            // Skip page break indicators and other non-element children
            if (child.classList.contains('page-break-indicator')) continue;

            // FILM-128: Skip title page block (already serialized at the start)
            if (child.dataset && child.dataset.elementType === 'title-page') continue;

            // Regular elements
            if (child.dataset && child.dataset.elementType) {
                serializeElement(child, false);
            }
        }

        return lines.join('\n').trim();
    }

    // Extract text from element, converting HTML formatting to Fountain markers
    function extractFormattedText(element) {
        let result = '';

        function processNode(node) {
            if (node.nodeType === Node.TEXT_NODE) {
                result += node.textContent;
            } else if (node.nodeType === Node.ELEMENT_NODE) {
                // Skip UI chrome the editor injects into blocks. These are
                // decorations, not screenplay text — the scene status icon was
                // being serialized into headings, leaving a stray glyph glued
                // to the slugline on every save.
                if (node.classList && (
                    node.classList.contains('scene-number-gutter') ||
                    node.classList.contains('scene-status-icon') ||
                    node.classList.contains('auto-detect-hint')
                )) {
                    return;
                }
                const tag = node.tagName.toLowerCase();
                const isBold = tag === 'b' || tag === 'strong' || node.style.fontWeight === 'bold';
                const isItalic = tag === 'i' || tag === 'em' || node.style.fontStyle === 'italic';
                const isUnderline = tag === 'u' || node.style.textDecoration?.includes('underline');

                // Determine markers
                let openMarker = '';
                let closeMarker = '';

                if (isBold && isItalic) {
                    openMarker = '***';
                    closeMarker = '***';
                } else if (isBold) {
                    openMarker = '**';
                    closeMarker = '**';
                } else if (isItalic) {
                    openMarker = '*';
                    closeMarker = '*';
                } else if (isUnderline) {
                    openMarker = '_';
                    closeMarker = '_';
                }

                result += openMarker;
                for (const child of node.childNodes) {
                    processNode(child);
                }
                result += closeMarker;
            }
        }

        for (const child of element.childNodes) {
            processNode(child);
        }

        return result;
    }

    function updateScriptStats() {
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;

        // Get Fountain text and parse it
        const fountainText = editorToFountain(editor);
        if (!fountainText.trim()) {
            document.getElementById('scriptStatsSummary').textContent = 'No content';
            return;
        }

        // Use the FountainParser's analyzeScreenplay function
        // Since the parser is isomorphic, we can use it in browser if loaded
        let parsed, stats;
        if (typeof FountainParser !== 'undefined') {
            parsed = FountainParser.parseFountain(fountainText);
            stats = FountainParser.analyzeScreenplay(parsed);
        } else {
            // Fallback: basic local analysis
            stats = analyzeScreenplayLocal(fountainText);
        }

        // FILM-126: Compute additional stats
        const lineCount = fountainText.split('\n').length;
        const pageCount = Math.ceil(lineCount / 55); // ~55 lines per page
        const runtimeMinutes = pageCount; // ~1 min per page
        const actionPct = stats.total_words > 0 ? Math.round((stats.action_words / stats.total_words) * 100) : 0;

        // Update summary in toggle bar
        document.getElementById('scriptStatsSummary').textContent =
            `${stats.total_words.toLocaleString()} words · ${stats.scene_count} scenes`;

        // Overview tab
        document.getElementById('statTotalWords').textContent = stats.total_words.toLocaleString();
        document.getElementById('statSceneCount').textContent = stats.scene_count;
        document.getElementById('statDialoguePct').textContent = stats.dialogue_percentage + '%';
        document.getElementById('statAvgSceneLen').textContent = stats.avg_scene_length + ' ln';

        // FILM-126: New overview stats
        const pageCountEl = document.getElementById('statPageCount');
        if (pageCountEl) pageCountEl.textContent = pageCount;

        const actionPctEl = document.getElementById('statActionPct');
        if (actionPctEl) actionPctEl.textContent = actionPct + '%';

        const runtimeEl = document.getElementById('statRuntime');
        if (runtimeEl) {
            const hours = Math.floor(runtimeMinutes / 60);
            const mins = runtimeMinutes % 60;
            runtimeEl.textContent = `Est. Runtime: ${hours > 0 ? hours + 'h ' : ''}${mins}min`;
        }

        // Dialogue tab - donut chart
        const donutCircle = document.getElementById('donutDialogue');
        const donutLabel = document.getElementById('donutPctLabel');
        if (donutCircle && donutLabel) {
            const circumference = 2 * Math.PI * 40; // radius = 40
            const dashLen = (stats.dialogue_percentage / 100) * circumference;
            donutCircle.setAttribute('stroke-dasharray', `${dashLen} ${circumference}`);
            donutLabel.textContent = stats.dialogue_percentage + '%';
        }

        // Update dialogue/action word counts (in both tabs)
        document.querySelectorAll('#statDialogueWords').forEach(el => {
            el.textContent = stats.dialogue_words.toLocaleString();
        });
        document.querySelectorAll('#statActionWords').forEach(el => {
            el.textContent = stats.action_words.toLocaleString();
        });

        // Scenes tab
        document.getElementById('statLongestScene').textContent = stats.longest_scene
            ? `Scene #${stats.longest_scene.scene_number} (${stats.longest_scene.length} lines)`
            : '—';
        document.getElementById('statShortestScene').textContent = stats.shortest_scene
            ? `Scene #${stats.shortest_scene.scene_number} (${stats.shortest_scene.length} lines)`
            : '—';

        // FILM-126: INT/EXT ratio bar
        const intExtBar = document.getElementById('intExtBar');
        if (intExtBar && stats.scenes_by_int_ext) {
            const total = Object.values(stats.scenes_by_int_ext).reduce((a, b) => a + b, 0);
            intExtBar.innerHTML = Object.entries(stats.scenes_by_int_ext)
                .map(([k, v]) => {
                    const pct = total > 0 ? Math.round((v / total) * 100) : 0;
                    return `<div class="stats-ratio-bar-segment" style="width:${pct}%">${k} (${v})</div>`;
                }).join('');
        }

        // FILM-126: Time of day ratio bar
        const timeOfDayBar = document.getElementById('timeOfDayBar');
        if (timeOfDayBar && stats.scenes_by_time) {
            const total = Object.values(stats.scenes_by_time).reduce((a, b) => a + b, 0);
            timeOfDayBar.innerHTML = Object.entries(stats.scenes_by_time)
                .map(([k, v]) => {
                    const pct = total > 0 ? Math.round((v / total) * 100) : 0;
                    return `<div class="stats-ratio-bar-segment" style="width:${pct}%">${k} (${v})</div>`;
                }).join('');
        }

        // FILM-126: Scene length bars
        const sceneLengthBars = document.getElementById('sceneLengthBars');
        if (sceneLengthBars && stats.scene_lengths) {
            const maxLen = Math.max(...stats.scene_lengths.map(s => s.length), 1);
            const LINES_PER_PAGE = 55;
            const shortThreshold = LINES_PER_PAGE * 0.5; // < 0.5 pages
            const longThreshold = LINES_PER_PAGE * 5;     // > 5 pages

            sceneLengthBars.innerHTML = stats.scene_lengths.slice(0, 20).map(s => {
                const pages = (s.length / LINES_PER_PAGE).toFixed(1);
                const pct = Math.round((s.length / maxLen) * 100);
                const isShort = s.length < shortThreshold;
                const isLong = s.length > longThreshold;
                const fillClass = isShort ? 'short' : isLong ? 'long' : '';

                return `
                    <div class="stats-scene-bar">
                        <span class="stats-scene-bar-label">Sc ${s.scene_number}</span>
                        <div class="stats-scene-bar-track">
                            <div class="stats-scene-bar-fill ${fillClass}" style="width:${pct}%"></div>
                        </div>
                        <span class="stats-scene-bar-value">${pages}pg</span>
                    </div>
                `;
            }).join('');

            if (stats.scene_lengths.length > 20) {
                sceneLengthBars.innerHTML += '<div style="font-size:10px;color:var(--gl-text-muted);text-align:center;margin-top:8px;">Showing first 20 scenes</div>';
            }
        }

        // Characters tab
        const charBreakdown = document.getElementById('statsCharacterBreakdown');
        const charEntries = Object.entries(stats.character_dialogue || {})
            .sort((a, b) => b[1] - a[1])
            .slice(0, 15);

        if (charEntries.length > 0) {
            const maxWords = charEntries[0][1];
            const totalDialogue = stats.dialogue_words || 1;

            charBreakdown.innerHTML = `
                <h5 style="margin-bottom:8px;">Dialogue by Character</h5>
                ${charEntries.map(([name, words]) => {
                    const pct = Math.round((words / totalDialogue) * 100);
                    return `
                    <div class="character-stat-bar">
                        <span class="character-stat-name" title="${escapeHtml(name)}">${escapeHtml(name)}</span>
                        <div class="character-stat-fill">
                            <div class="character-stat-fill-inner" style="width: ${Math.round(words / maxWords * 100)}%"></div>
                        </div>
                        <span class="character-stat-count">${words} (${pct}%)</span>
                    </div>
                `;}).join('')}
            `;
        } else {
            charBreakdown.innerHTML = '<p class="text-sm text-muted">No character dialogue detected.</p>';
        }
    }

    // Fallback local analysis if FountainParser not available
    function analyzeScreenplayLocal(text) {
        const lines = text.split('\n');
        let totalWords = 0;
        let dialogueWords = 0;
        let actionWords = 0;
        let sceneCount = 0;
        const sceneLengths = [];
        let currentSceneLength = 0;
        let inDialogue = false;
        const characterDialogue = {};
        let currentCharacter = null;
        const scenesByIntExt = {};
        const scenesByTime = {};

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;

            const words = trimmed.split(/\s+/).length;
            totalWords += words;

            // Scene heading detection
            if (/^(INT|EXT|EST|INT\.?\/?EXT|I\/E)[\.\s]/i.test(trimmed) || AUTO_FORMAT_RULES.patterns.forcedSceneHeading.test(trimmed)) {
                if (currentSceneLength > 0) {
                    sceneLengths.push({ scene_number: String(sceneCount), length: currentSceneLength });
                }
                sceneCount++;
                currentSceneLength = 1;
                inDialogue = false;

                // Track INT/EXT
                const intExtMatch = trimmed.match(/^(INT|EXT|EST|INT\.?\/?EXT|I\/E)/i);
                if (intExtMatch) {
                    const key = intExtMatch[1].toUpperCase();
                    scenesByIntExt[key] = (scenesByIntExt[key] || 0) + 1;
                }

                // Track time of day
                const timeMatch = trimmed.match(/[-–—]\s*(DAY|NIGHT|MORNING|EVENING|DUSK|DAWN|CONTINUOUS|LATER)/i);
                if (timeMatch) {
                    const key = timeMatch[1].toUpperCase();
                    scenesByTime[key] = (scenesByTime[key] || 0) + 1;
                }
            }
            // Character detection (all caps, not too long)
            else if (/^[A-Z][A-Z0-9\s\-'\.]+(\s*\([^)]+\))?$/.test(trimmed) && trimmed.length < 40) {
                currentCharacter = trimmed.replace(/\s*\([^)]+\)\s*$/, '');
                if (!characterDialogue[currentCharacter]) {
                    characterDialogue[currentCharacter] = 0;
                }
                inDialogue = true;
                currentSceneLength++;
            }
            // Dialogue (after character)
            else if (inDialogue && !trimmed.startsWith('(')) {
                dialogueWords += words;
                if (currentCharacter) {
                    characterDialogue[currentCharacter] += words;
                }
                currentSceneLength++;
            }
            // Action
            else {
                actionWords += words;
                inDialogue = false;
                currentSceneLength++;
            }
        }

        // Save final scene
        if (currentSceneLength > 0) {
            sceneLengths.push({ scene_number: String(sceneCount), length: currentSceneLength });
        }

        const avgSceneLength = sceneLengths.length > 0
            ? Math.round(sceneLengths.reduce((sum, s) => sum + s.length, 0) / sceneLengths.length * 10) / 10
            : 0;

        const sortedScenes = [...sceneLengths].sort((a, b) => b.length - a.length);

        return {
            total_words: totalWords,
            dialogue_words: dialogueWords,
            action_words: actionWords,
            dialogue_percentage: totalWords > 0 ? Math.round(dialogueWords / totalWords * 100) : 0,
            scene_count: sceneCount,
            scenes_by_int_ext: scenesByIntExt,
            scenes_by_time: scenesByTime,
            avg_scene_length: avgSceneLength,
            longest_scene: sortedScenes[0] || null,
            shortest_scene: sortedScenes[sortedScenes.length - 1] || null,
            character_dialogue: characterDialogue,
            scene_lengths: sceneLengths // FILM-126: Include for scene length bars
        };
    }

    function loadScreenplayPage() {
        loadScriptVersions();
        loadLatestFountain();
        // FILM-121: Check for entity suggestions
        checkScreenplaySuggestions();
        // FILM-124: Update scene status icons after a small delay to ensure editor is rendered
        setTimeout(updateSceneStatusIcons, 500);
        /*
         * The gutter is painted AFTER the editor has content and a layout.
         *
         * Its markers are positioned from each scene heading's own offsetTop,
         * so painting before the Fountain has rendered puts every marker at 0 —
         * which looks like the gutter is broken rather than early. The shot
         * codes come from the shot list, which the same delay covers.
         */
        SCRIPT_TIMING = null;
        setTimeout(async () => {
            // The shot codes are a bonus, not a prerequisite: a screenplay with
            // no breakdown yet still has eighths and a screen time, and failing
            // the whole gutter for want of a shot list would hide them.
            try {
                const data = await api(`/projects/${state.currentProject.id}/shotlist`);
                state.shots = data.shots || [];
            } catch (_) { /* no breakdown yet */ }
            renderScriptGutter();
        }, 600);
    }

    // FILM-124: Update scene heading status icons in the screenplay editor
    function updateSceneStatusIcons() {
        const editor = document.getElementById('screenplayEditor');
        if (!editor || !state.scenes || state.scenes.length === 0) return;

        const sceneHeadings = editor.querySelectorAll('[data-element-type="scene-heading"]');

        sceneHeadings.forEach((heading, index) => {
            // Remove existing status icon if any
            const existingIcon = heading.querySelector('.scene-status-icon');
            if (existingIcon) existingIcon.remove();

            // Try to match scene by number or location
            const headingText = heading.textContent.trim();
            const sceneNumAttr = heading.dataset.sceneNumber;

            // Find matching scene in state
            let matchedScene = null;

            // First try by scene number attribute
            if (sceneNumAttr) {
                matchedScene = state.scenes.find(s => String(s.scene_number) === sceneNumAttr);
            }

            // Fallback: try by location
            if (!matchedScene) {
                const locMatch = headingText.match(/(?:INT|EXT|INT\.?\/EXT)[\.\s]+([^-]+)/i);
                if (locMatch) {
                    const location = locMatch[1].trim().toUpperCase();
                    matchedScene = state.scenes.find(s =>
                        s.location && s.location.toUpperCase() === location
                    );
                }
            }

            // Fallback: match by index if scene count matches heading count
            if (!matchedScene && state.scenes.length === sceneHeadings.length) {
                matchedScene = state.scenes[index];
            }

            // Add status icon if we found a matching scene
            if (matchedScene && matchedScene.status) {
                const icon = document.createElement('span');
                icon.className = `scene-status-icon ${matchedScene.status}`;
                icon.title = getSceneStatusLabel(matchedScene.status);

                // Icon based on status
                if (matchedScene.status === 'broken_down') {
                    icon.innerHTML = '✓';
                } else if (matchedScene.status === 'written') {
                    icon.innerHTML = '⏱';
                } else {
                    icon.innerHTML = '○';
                }

                heading.insertBefore(icon, heading.firstChild);
            }
        });
    }

    function getSceneStatusLabel(status) {
        const labels = {
            'written': 'Ready for breakdown',
            'broken_down': 'Breakdown complete',
            'pending': 'Not yet written',
            'removed': 'Removed from screenplay', failed: 'FAILED' };
        return labels[status] || status;
    }

    // FILM-124: Re-render screenplay editor (called after breakdowns)
    function renderScreenplayEditor() {
        // Just update status icons - don't reload entire editor
        updateSceneStatusIcons();
    }

    // ══════════════════════════════════════════════════════════════
    // CHARACTERS
    // ══════════════════════════════════════════════════════════════
    // ── Entity inspector ───────────────────────────────────────────────────
    //
    // A card shows a 48px avatar, which cannot answer the question anyone
    // actually has about a generated plate: is this the right person, in the
    // right clothes, in the right medium. The plate is the thing that
    // conditions every frame the subject appears in, so it is worth seeing at
    // size, next to the text it was generated from.

    /** Which fields matter per kind, and what each is FOR. */
    const ENTITY_FIELDS = {
        character: [
            { key: 'appearance_prompt', label: 'Appearance', note: 'This is what reaches the image prompt and what the plate is generated from.' },
            { key: 'description', label: 'Description' },
            { key: 'age_range', label: 'Age' }, { key: 'gender', label: 'Gender' },
            { key: 'build', label: 'Build' }, { key: 'hair', label: 'Hair' },
            { key: 'ethnicity', label: 'Ethnicity' }, { key: 'distinguishing', label: 'Distinguishing' },
            { key: 'personality_notes', label: 'Personality' },
        ],
        location: [
            { key: 'description', label: 'Description', note: 'This is what reaches the image prompt and what the plate is generated from.' },
            { key: 'reference_prompt', label: 'Reference prompt' },
            { key: 'lighting_default', label: 'Lighting' },
            { key: 'time_of_day_default', label: 'Time of day' },
            { key: 'atmosphere_notes', label: 'Atmosphere' }, { key: 'sound_notes', label: 'Sound' },
        ],
        prop: [
            { key: 'visual_prompt', label: 'Visual prompt', note: 'This is what reaches the image prompt and what the plate is generated from.' },
            { key: 'description', label: 'Description' },
            { key: 'category', label: 'Category' }, { key: 'notes', label: 'Notes' },
        ],
    };

    async function inspectEntity(kind, id) {
        const modal = document.getElementById('entityInspectModal');
        const body = document.getElementById('entityInspectBody');
        document.getElementById('entityInspectTitle').textContent = 'Loading…';
        body.innerHTML = '';
        showModal('entityInspectModal');

        let row;
        try {
            const list = kind === 'character' ? state.characters
                : kind === 'location' ? state.locations : state.props;
            row = (list || []).find(x => x.id === id);
            if (!row) {
                const path = kind === 'character' ? 'characters' : kind === 'location' ? 'locations' : 'props';
                const res = await api(`/projects/${state.currentProject.id}/${path}`);
                row = (res[path] || []).find(x => x.id === id);
            }
        } catch (err) {
            body.innerHTML = `<p class="text-muted">Could not load: ${esc(err.message)}</p>`;
            return;
        }
        if (!row) { body.innerHTML = '<p class="text-muted">Not found.</p>'; return; }

        document.getElementById('entityInspectTitle').textContent = row.name || 'Details';
        const img = row.reference_image_url || row.image_url || row.plate_url;

        const fields = (ENTITY_FIELDS[kind] || [])
            .map(f => {
                const v = String(row[f.key] || '').trim();
                if (!v) return '';
                // The character count is shown because it is the number that
                // decides how much survives into a keyframe prompt.
                return `<div style="margin-bottom:12px;">
                    <div class="section-label" style="margin-bottom:4px;">${esc(f.label)}
                        <span class="text-muted" style="text-transform:none;letter-spacing:0;">· ${v.length} chars</span></div>
                    <div class="text-sm" style="line-height:1.5;">${esc(v)}</div>
                    ${f.note ? `<div class="text-sm text-muted" style="margin-top:4px;">${esc(f.note)}</div>` : ''}
                </div>`;
            }).filter(Boolean).join('');

        // Whether this subject's plate still matches the text beside it. The
        // detection existed and had one remedy — regenerate — which spends
        // money to replace an image someone chose, and cannot promise to
        // reproduce it. "Still right" needed to be sayable.
        /*
         * THE BANNER MUST NOT HOLD THE MODAL SHUT.
         *
         * This awaited the whole-project staleness report before writing a
         * single character of the body, so opening a location with a plate
         * showed a titled, empty box for as long as that report took — which
         * grows with the number of generated assets. It read as "modals are
         * slow when a picture is involved"; the picture had nothing to do with
         * it, and neither did the modal.
         *
         * The body renders now. The banner is information about the plate, not
         * a gate on reading the record, so it arrives when it arrives.
         */
        let staleBanner = '';
        body.innerHTML = `
            ${staleBanner}
            <div style="display:flex;gap:20px;flex-wrap:wrap;">
                <div style="flex:1 1 340px;min-width:280px;">
                    ${img
                        ? `<img src="${esc(plateSrc(img, 480))}" style="width:100%;border-radius:6px;display:block;cursor:zoom-in;"
                             title="Click to see it full size"
                             onclick="openPlateViewer('${API_BASE}${esc(img)}', ${jsAttr(row.name || 'Reference')})"
                             onerror="this.parentElement.innerHTML='<p class=text-muted>The plate file is missing.</p>'">`
                        : '<p class="text-sm text-muted">No plate generated yet. Generate one so every frame with this subject draws the same thing.</p>'}
                </div>
                <div style="flex:1 1 340px;min-width:280px;">
                    ${fields || '<p class="text-sm text-muted">Nothing described yet. An entity with no description reaches the image prompt as a bare name, and every frame invents its own version of it.</p>'}
                </div>
            </div>
            ${kind === 'location' ? `<div id="locationViewsSection" style="margin-top:18px;"></div>` : ''}
            ${kind === 'character' ? `<div id="characterViewsSection" style="margin-top:18px;"></div>` : ''}`;

        /*
         * THE WHOLE TURNAROUND, where a person looks for it.
         *
         * A reference sheet is front, side and back. This panel showed ONE
         * picture — whichever the card had picked — so two of the three plates
         * a director had just paid for were invisible unless they found a
         * separate button. Locations already listed their views here; the
         * character, which is the subject a turnaround is FOR, did not.
         */
        if (kind === 'character') renderCharacterViewsInto('characterViewsSection', id);

        // Now that the record is readable, ask whether the plate is behind.
        (async () => {
            try {
                const rep = await api(`/projects/${state.currentProject.id}/staleness`);
                const hit = (rep.stale || []).find(x => x.shot_id === undefined
                    && String(x.file_name || '').toLowerCase()
                        .includes(String(row.name || '').toLowerCase().replace(/\s+/g, '_')));
                if (!hit || !body.isConnected) return;
                const banner = document.createElement('div');
                banner.className = 'card';
                banner.style.cssText = 'margin-bottom:12px;border-color:var(--gl-warning,#f59e0b);';
                banner.innerHTML = `<strong>Plate is out of date</strong>
                    <p class="text-sm" style="margin:6px 0;">${esc(hit.reason || 'inputs changed since it was generated')}</p>
                    <div style="display:flex;gap:8px;">
                        <button class="btn btn-secondary btn-sm" onclick="acceptPlate('${hit.asset_id}','${kind}')"
                                title="Keep this image and record it as current">Still correct</button>
                        <button class="btn btn-secondary btn-sm" onclick="regeneratePlate('${kind}','${id}')"
                                title="Generate a new plate — replaces this one and costs credits">Regenerate</button>
                    </div>`;
                body.insertBefore(banner, body.firstChild);
            } catch (_) { /* the banner is information, not a gate */ }
        })();

        // A LOCATION OWNS ITS VIEWS, so they live on the location.
        //
        // Views shipped with their only control inside a shot's blocking panel,
        // so the plates belonging to a place could be added from anywhere except
        // that place. GET /plate/views has always returned all of them with
        // their images; nothing here asked.
        if (kind === 'location') renderLocationViews(id);
    }

    /**
     * Every photographed view of a location, and the way to add another.
     *
     * A location has ONE default plate and a growing set of views; a shot points
     * at whichever it is facing. Generated independently, four views of a
     * cul-de-sac produce four different cul-de-sacs — so a new view is anchored
     * on an existing plate and is the same street from a new position.
     */
    /*
     * A RENDER THAT THROWS MUST SAY SO.
     *
     * This wrote "Loading views…" and then built its markup with no guard, so
     * one bad reference left the panel showing "Loading" permanently — which
     * reads as the plates being missing, and was reported as exactly that. A
     * spinner that never resolves is worse than an error: an error can be acted
     * on.
     */
    async function renderLocationViews(locationId) {
        const host = document.getElementById('locationViewsSection');
        if (!host) return;
        host.innerHTML = '<p class="text-sm text-muted">Loading views…</p>';

        // The whole response: the location's NAME is on it, and the view cards
        // need it for the viewer's title. Reaching for an `r` that was never in
        // scope here threw mid-render and left the panel on "Loading views…"
        // forever — a source check for openPlateViewer passed while the panel
        // was dead, which is the same grep-versus-behaviour gap the truncated
        // onclick had.
        let payload = { views: [], location: '' };
        try { payload = await api(`/locations/${locationId}/plate/views`); }
        catch (err) { host.innerHTML = `<p class="text-sm text-muted">Could not read the views: ${esc(err.message)}</p>`; return; }
        const views = payload.views || [];
        const locationName = payload.location || 'Location';

        const card = v => `
            <div style="flex:0 0 200px;position:relative;">
                ${v.available
                    ? `<img src="${esc(plateSrc(v.image_url, 480))}"
                             style="width:100%;border-radius:6px;display:block;cursor:zoom-in;"
                             title="Click to see it full size"
                             onclick="openPlateViewer('${API_BASE}${esc(v.image_url)}', ${jsAttr(locationName + ' — ' + (v.label || v.view || 'default'))})">`
                    : `<div class="text-sm text-muted" style="padding:20px;border:1px dashed var(--gl-border,#444);border-radius:6px;">
                         ${esc(v.unavailable_reason || 'the file for this view is missing')}
                       </div>`}
                <button class="btn btn-secondary btn-sm"
                        style="position:absolute;top:6px;right:6px;padding:2px 7px;line-height:1;"
                        title="Delete this view"
                        onclick="deleteLocationView('${locationId}', ${JSON.stringify(v.view || '__default__').replace(/"/g, '&quot;')})">&times;</button>
                ${v.available ? `<button class="btn btn-secondary btn-sm"
                        style="position:absolute;top:6px;left:6px;padding:2px 7px;line-height:1;"
                        title="Keep this picture and change one thing — wet the road, add fog, move the light"
                        onclick="refineLocationView('${locationId}', ${JSON.stringify(v.view || '').replace(/"/g, '&quot;')})">Refine</button>` : ''}
                <div class="text-sm" style="margin-top:6px;line-height:1.4;">${esc(v.label)}</div>
            </div>`;

        try {
        host.innerHTML = `
            <h4 style="margin:0 0 6px;">Views of this location</h4>
            <p class="text-sm text-muted" style="margin:0 0 10px;line-height:1.5;">
                A shot uses the view it is pointed at. A reverse angle given the only view you have
                is handed a photograph of what is behind its camera — which is where invented streets
                come from. Generate the angles you actually shoot; each one is paid for once.
            </p>
            <div style="display:flex;gap:12px;flex-wrap:wrap;">${views.map(card).join('')}</div>
            <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
                <button class="btn btn-primary btn-sm" id="compassSweepBtn"
                        onclick="sweepLocationCompass('${locationId}', this)"
                        title="Photograph east, south and west as quarter turns from the plate you already have">
                    &#129517; Photograph all four sides
                </button>
                <button class="btn btn-secondary btn-sm"
                        onclick="addLocationView('${locationId}')"
                        title="Describe a camera position; it is photographed from the plate you already have">
                    + Photograph a new view&hellip;
                </button>
            </div>
            <p class="text-sm text-muted" style="margin:8px 0 0;line-height:1.5;">
                All four sides turns the plate you have into north, east, south and west &mdash; each one
                a quarter turn from it, so they agree with each other. It is what a reverse angle needs.
            </p>`;
        } catch (err) {
            /*
             * A render that throws must SAY so. Without this, one bad
             * reference left the panel on "Loading views…" permanently and the
             * plates read as missing — which is how three perfectly good
             * compass views were reported as lost.
             */
            host.innerHTML = '<p class="text-sm">Could not draw the views: ' + esc(err.message)
                + '. The plates are still there — this is a display fault.</p>';
        }
    }

    /**
     * All four sides of a place, from the one plate it already has.
     *
     * A location with one plate hands every shot the same side of the street,
     * so a shot pointing the other way is given a picture of what is BEHIND
     * its camera and invents the rest — which is what blocked 2AA.
     *
     * The cost leads the confirmation, because this is the one control on the
     * page that spends more than one generation in a press.
     */
    /**
     * Sweep the compass: the sides this location is missing.
     *
     * Through the shared gate, so the generator, model, quality and size are a
     * choice. The plan is FREE and is what prices the sweep, so the number in
     * the confirmation is the number that will be charged.
     */
    const SWEEP_NOTE = 'Each side is anchored on the plate you already have, so they are four '
        + 'sides of one place rather than four places. The prompt is per side and is shown when '
        + 'each is generated; the choices here apply to the whole sweep.';

    async function sweepLocationCompass(locationId, btn) {
        return confirmPaidImage({
            title: 'Sweep the compass',
            capability: 'image',
            previewUrl: `/locations/${locationId}/plate/compass/plan`,
            note: SWEEP_NOTE,
            editable: false,
            notEditableWhy: 'Each side is generated from its own prompt, shown as it runs.',
            send: async choices => {
                setStatus('Photographing the other sides…', true);
                if (btn) btn.disabled = true;
                try {
                    const r = await api(`/locations/${locationId}/plate/compass`, {
                        method: 'POST', body: JSON.stringify(choices || {}),
                    });
                    const made = (r && r.generated) || [];
                    const missed = (r && r.not_attempted) || [];
                    setStatus(missed.length
                        ? `${made.length} side(s) made; not attempted: ${missed.join(', ')}`
                        : `${made.length} side(s) generated.`);
                    if (typeof loadLocations === 'function') loadLocations();
                } catch (err) { setStatus('Could not sweep: ' + err.message); }
                finally { if (btn) btn.disabled = false; }
            },
        });
    }

    /**
     * Remove one view. The set could only grow before this.
     *
     * The compass sweep SKIPS a side that already exists, so without a delete a
     * bad side was permanent AND blocked the good one from ever being bought.
     *
     * The confirmation names what is lost, because a plate is a picture that was
     * paid for, and it names the shots pointed at it AFTER the fact rather than
     * repointing them: which side a shot looks at is a decision the director
     * made, and silently moving it to another direction is the bug views exist
     * to prevent.
     */
    async function deleteLocationView(locationId, view) {
        const isDefault = view === '__default__';
        if (!confirm(isDefault
            ? 'Delete the original plate?\n\nIt is the picture the other sides are turns from, and the '
              + 'fallback for every shot that names no view. The compass sweep cannot run without it.'
            : `Delete the "${view}" view?\n\nThe image is removed and cannot be recovered — `
              + 'photographing it again costs credits.')) return;
        setStatus('Deleting the view…', true);
        try {
            const r = await api(`/locations/${locationId}/plate/views/${encodeURIComponent(view)}`,
                { method: 'DELETE' });
            const pointed = (r.shots_pointing_here || []);
            setStatus(pointed.length
                ? `View deleted. ${pointed.join(', ')} named it — those shots now fall back to the `
                  + 'original plate until you point them at another side.'
                : 'View deleted.');
        } catch (err) {
            setStatus('Could not delete the view: ' + err.message);
        }
        renderLocationViews(locationId);
    }

    /**
     * Keep this plate and change one thing.
     *
     * A plate could only be regenerated wholesale, so "the same street but
     * wetter" was a fresh roll of the dice on a picture that conditions every
     * frame the location appears in.
     *
     * This is also the operation this provider is best at: a new VIEW has to be
     * painted from words because an edit cannot move the camera, while a refine
     * keeps the camera and changes one thing — precisely what an image-to-image
     * endpoint does.
     */
    async function refineLocationView(locationId, view) {
        const what = prompt('What should change?\n\n'
            + 'One instruction — "wetter road", "overcast instead of blue hour". The picture is '
            + 'attached, so do not re-describe the place.');
        if (!what || !what.trim()) return;
        const q = new URLSearchParams({ instruction: what.trim(), ...(view ? { view } : {}) });
        return confirmPaidImage({
            title: 'Refine this plate',
            note: 'This REPLACES the plate for this view. The previous picture is gone.',
            previewUrl: `/locations/${locationId}/plate/refine-preview?${q}`,
            send: async choices => {
                setStatus('Refining plate...', true);
                try {
                    await api(`/locations/${locationId}/plate/refine`, { method: 'POST',
                        body: JSON.stringify({ instruction: what.trim(), ...(view ? { view } : {}), ...choices }) });
                    setStatus('Plate refined.');
                    loadLocations();
                } catch (err) { setStatus('Could not refine: ' + err.message); }
            },
        });
    }

    /** Ask for a camera position and photograph it, anchored on what exists. */
    /**
     * Photograph this location from a new position.
     *
     * The view is asked for first because it IS the subject of the prompt, and
     * then the shared gate shows what that prompt became — with the provider,
     * model, quality and size for this one generation. It was a bare prompt()
     * followed by an immediate POST, so a director never saw what was sent.
     */
    async function addLocationView(locationId, onDone) {
        const view = prompt('Describe where the camera stands, the way you would tell a photographer.\n\n'
            + 'For example: from the far kerb, looking back across the bulb');
        if (!view || !view.trim()) return;
        return regeneratePlate('location', locationId, view.trim(),
            typeof onDone === 'function' ? onDone : () => {
                if (typeof loadLocations === 'function') loadLocations();
            });
    }

    /** Keep the image, record it as current for the inputs it now sits beside. */
    async function acceptPlate(assetId, kind) {
        try {
            await api(`/assets/${assetId}/accept`, { method: 'POST', body: JSON.stringify({ kind: kind + '_plate' }) });
            setStatus('Plate accepted as current — nothing was regenerated.');
            closeModal('entityInspectModal');
        } catch (err) { setStatus('Could not accept: ' + err.message); }
    }

    /** The other remedy, named so the cost is visible before it is chosen. */
    async function regeneratePlate(kind, subjectId, view, onDone) {
        const base = kind === 'character' ? `/characters/${subjectId}/refsheet`
            : kind === 'prop' ? `/props/${subjectId}/plate`
            : `/locations/${subjectId}/plate`;
        /*
         * `/plate/plate-preview`, not `/plate-preview`.
         *
         * The route dispatches the preview INSIDE the `urlParts[3] === 'plate'`
         * block, so `/locations/:id/plate-preview` never enters it -- it fell
         * through to the plain location GET, which answers 200 with the
         * location row and no `prompt` at all. The gate then opened with an
         * empty prompt and no facts, which is indistinguishable from the
         * dialog being broken and is exactly how it was reported.
         */
        const previewUrl = kind === 'character'
            ? `${base}/preview`
            : `${base}/plate-preview${view ? `?view=${encodeURIComponent(view)}` : ''}`;
        return confirmPaidImage({
            title: 'Generate this plate',
            note: 'A plate conditions every frame its subject appears in. This replaces the '
                + 'current one for this view and costs credits.',
            previewUrl,
            send: async choices => {
                setStatus('Generating plate...', true);
                try {
                    await api(`${base}/generate`, { method: 'POST',
                        body: JSON.stringify({ ...choices, ...(view ? { view } : {}) }) });
                    setStatus('Plate generated.');
                    /*
                     * The caller's own refresh, when it has one. A subject
                     * sheet has to repaint its own plates; the entity lists
                     * repaint theirs. Delegating here rather than duplicating
                     * the dialog is what closed four ungated buttons at once.
                     */
                    if (typeof onDone === 'function') { onDone(); return; }
                    if (kind === 'character') loadCharacters();
                    else if (kind === 'prop') loadProps();
                    else loadLocations();
                } catch (err) { setStatus('Could not generate: ' + err.message); }
            },
        });
    }

    async function loadCharacters() {
        if (!state.currentProject) return;
        try {
            const data = await api('/projects/' + state.currentProject.id + '/characters');
            state.characters = data.characters || [];
            const el = document.getElementById('characterGrid');
            if (state.characters.length === 0) {
                el.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><div class="icon">&#128100;</div><h3>No characters</h3><p>Add characters for your film production.</p></div>`;
            } else {
                el.innerHTML = state.characters.map(c => `
                    <div class="entity-card" style="cursor:pointer;" onclick="openCharacterSheet('${c.id}')" title="Open the character sheet">
                        <div class="entity-card-header">
                            ${c.reference_image_url
                                ? '<img src="' + plateSrc(c.reference_image_url, 160) + '" style="width:48px;height:48px;border-radius:50%;object-fit:cover;flex-shrink:0;cursor:zoom-in;" title="Click to see the plate full size"'
                                    // stopPropagation: the card is itself clickable and opens the
                                    // inspector, so without this you get both and the one you
                                    // asked for is underneath.
                                    + ' onclick="event.stopPropagation(); openPlateViewer(\'' + API_BASE + c.reference_image_url + '\', ' + jsAttr(c.name) + ')"'
                                    + ' onerror="this.outerHTML=\'<div class=entity-avatar>' + esc(c.name.charAt(0)) + '</div>\'">'
                                : '<div class="entity-avatar">' + esc(c.name.charAt(0)) + '</div>'}
                            <div>
                                <h3>${esc(c.name)}</h3>
                                <p class="text-sm text-muted">${[
                                    c.age_range ? esc(c.age_range) : null,
                                    c.gender ? esc(c.gender) : null,
                                    c.height_m ? esc(c.height_m) + 'm' : null,
                                ].filter(Boolean).join(' &middot; ') || ''}${
                                    /*
                                     * What is MISSING, said where it is noticed.
                                     *
                                     * Both fields already rendered here and an
                                     * absent one produced an empty line, which
                                     * reads as the field not existing — it was
                                     * reported as exactly that. They are not
                                     * decoration: voice casting ranks the
                                     * catalogue by them, so an unrecorded
                                     * gender means twenty-one voices in
                                     * arbitrary order.
                                     */
                                    (!c.age_range || !c.gender)
                                    ? `<a class="text-sm" style="cursor:pointer;color:var(--gl-accent,#818cf8);"
                                          onclick="event.stopPropagation(); editCharacter('${c.id}')"
                                          title="Voice casting ranks the catalogue by these">${
                                        c.age_range || c.gender ? ' &middot; ' : ''}+ ${
                                        [!c.gender ? 'gender' : null, !c.age_range ? 'age' : null]
                                            .filter(Boolean).join(' &amp; ')}</a>`
                                    : ''}</p>
                            </div>
                        </div>
                        <p>${esc(c.description || 'No description')}</p>
                        <div class="tag-row">
                            ${c.has_voice_profile ? '<span class="tag" style="background:rgba(34,197,94,0.15);color:#4ade80;">Voice</span>' : ''}
                            ${c.costume_count > 0 ? '<span class="tag">' + c.costume_count + ' costume(s)</span>' : ''}
                            ${c.lora_id ? '<span class="tag">LoRA</span>' : ''}
                        </div>
                        <div class="card-actions">
                            <!--
                              Two buttons.
                              Regen Image, Orbit Sheet, Views, Upload, Gallery
                              and Voice all came off this row: every one of them
                              is something you do while LOOKING at the
                              character, and eight controls on a 260px tile in a
                              grid of twelve is a worse place to do it than a
                              sheet with room. They live in openCharacterSheet(),
                              and tests/character-sheet.test.js holds each of
                              them to still being reachable — removing a button
                              is only a simplification if the thing it did has a
                              home.
                            -->
                            <button class="btn btn-secondary btn-sm" onclick="event.stopPropagation(); editCharacter('${c.id}')">Edit</button>
                            <button class="btn btn-danger btn-sm" onclick="event.stopPropagation(); deleteCharacter('${c.id}')">Delete</button>
                        </div>
                    </div>`).join('');
            }
        } catch (err) { setStatus('Error: ' + err.message); }
    }


    /*
     * THE TURNAROUND, and which view actually reaches a prompt.
     *
     * Three plates are generated and exactly ONE is attached to a frame — the
     * reference budget is three on Runway and five on Meshy, shared with the
     * location, the props and the anchor, so a second view of the same person
     * costs a slot a subject with no picture at all would otherwise get.
     * Saying which one is doing the work is the point of this panel: it was
     * silently the BACK, because the picker took the newest row.
     */
    /** The turnaround as markup. Shared by the detail modal and the Views button. */
    function characterViewsHtml(r, charId) {
        return r.views.length ? `
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">
                    ${r.views.map(v => `
                        <div style="border:1px solid ${v.is_identity_plate ? 'var(--gl-accent,#6690ff)' : 'var(--gl-border-subtle)'};border-radius:8px;padding:8px;min-width:0;">
                            ${v.image_url
                                /* API_BASE, because the route returns a PATH and the
                                   page is served from a different port — without it
                                   every picture is a perfectly good string and a 404. */
                                ? `<img src="${esc(plateSrc(v.image_url, 480))}" alt="${esc(v.view)}"
                                       style="width:100%;border-radius:6px;display:block;cursor:zoom-in;"
                                       title="Click to see it full size"
                                       onclick="openPlateViewer('${API_BASE}${esc(v.image_url)}', ${jsAttr(r.character + ' — ' + v.view)})">`
                                : `<div class="text-sm text-muted" style="padding:24px 8px;text-align:center;">${esc(v.unavailable_reason || 'No picture')}</div>`}
                            <div class="flex-between" style="margin-top:6px;">
                                <strong class="text-sm">${esc(v.view)}</strong>
                                ${v.is_identity_plate ? '<span class="badge">used in every frame</span>' : ''}
                            </div>
                            <div class="card-actions">
                                <button class="btn btn-danger btn-sm"
                                    onclick="deleteCharacterView('${charId}','${esc(v.view)}')">Delete</button>
                            </div>
                        </div>`).join('')}
                </div>
                <p class="text-sm text-muted" style="margin-top:12px;line-height:1.5;">${esc(r.note)}</p>`
            : '<p class="text-sm text-muted">No plates yet. Generate Image makes a front/side/back turnaround.</p>';
    }

    /**
     * Render a character's views into a container.
     *
     * One renderer for both surfaces — the detail modal and the Views button —
     * because two copies is exactly how the board and the viewer came to
     * disagree about their own markup tools.
     */
    async function renderCharacterViewsInto(hostId, charId) {
        const host = document.getElementById(hostId);
        if (!host) return;
        host.innerHTML = '<p class="text-sm text-muted">Loading views…</p>';
        try {
            const r = await api(`/characters/${charId}/refsheet/views`);
            if (!host.isConnected) return;
            host.innerHTML = r.views.length > 1 || (r.views.length === 1 && r.views[0].view !== 'front')
                ? `<div class="section-label" style="margin-bottom:8px;">Reference views &middot; ${r.views.length}</div>`
                  + characterViewsHtml(r, charId)
                : '';
        } catch (err) {
            host.innerHTML = `<p class="text-sm text-muted">Could not read the views: ${esc(err.message)}</p>`;
        }
    }

    async function showCharacterViews(charId) {
        try {
            const r = await api(`/characters/${charId}/refsheet/views`);
            const body = characterViewsHtml(r, charId);

            // Reuses the entity inspector rather than inventing a second
            // modal: two panels showing a subject's pictures is how they come
            // to disagree about which one is in use.
            document.getElementById('entityInspectTitle').textContent = `${r.character} — reference views`;
            document.getElementById('entityInspectBody').innerHTML = body;
            showModal('entityInspectModal');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteCharacterView(charId, view) {
        // Names what is lost and what is not. A plate cost money; the bytes
        // are set aside rather than destroyed, and saying so is the difference
        // between a confirmation people read and one they click through.
        if (!confirm(`Delete the ${view} view of this character?\n\n`
            + `It stops being used in every frame this character appears in, and stops being listed.\n`
            + `The picture file is moved to a "deleted" folder rather than destroyed, so it can be `
            + `put back by hand — but nothing in the app will do that for you.`)) return;
        try {
            await api(`/characters/${charId}/refsheet/views/${encodeURIComponent(view)}`, { method: 'DELETE' });
            setStatus(`${view} view deleted`);
            closeModal('entityInspectModal');
            loadCharacters();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // FILM-122: Track original name for rename confirmation
    let editingCharacterOriginalName = '';
    let editingLocationOriginalName = '';

    /* ── the character sheet ───────────────────────────────────────────────
     *
     * The card carried eight buttons and clicking it did nothing. Every one of
     * those is something you do while LOOKING at the character, so they live
     * here. Built to design_handoff_character_card: official views top-left,
     * everything written top-right, wardrobe and palette under it, and a
     * full-width concept band across the bottom.
     */

    // Mirrors lib/character-sheet.js. The page cannot require a node module
    // (build.target: single-html), so the registries are duplicated and held in
    // lockstep by tests/character-sheet.test.js — the screenplay-pagination
    // precedent.
    const CS_VIEWS = [
        { id: 'front', label: 'Front', caption: 'front plate' },
        { id: 'side-left', label: 'Left', caption: 'left profile' },
        { id: 'side-right', label: 'Right', caption: 'right profile' },
        { id: 'back', label: 'Back', caption: 'back plate' },
    ];
    const CS_CATEGORIES = [
        { id: 'sketch', label: 'Sketch' }, { id: 'costume', label: 'Costume' },
        { id: 'face', label: 'Face' }, { id: 'mood', label: 'Mood' },
    ];
    const CS_LEGACY = { side: 'side-left', 'three-quarter': 'front', 'back-three-quarter': 'back', right: 'side-right', left: 'side-left', profile: 'side-left' };

    let SHEET = { id: null, character: null, gallery: [], costumes: [],
        filter: 'all', palette: [] };

    /**
     * Run something that spends, with a spinner on the button.
     *
     * A generation takes up to a minute, and without this the page looks
     * exactly as it did before the click — which reads as the button not
     * working and invites a second press on a paid action. The board learned
     * this once; the sheet had none of it.
     *
     * `finally` is the load-bearing part: a spinner that keeps turning after a
     * failure is worse than none, because it says work is still happening when
     * nothing is.
     */
    async function csBusy(label, work) {
        const bar = document.getElementById('csChips');
        const badge = document.createElement('span');
        badge.className = 'cs-chip cs-busy';
        badge.innerHTML = '<span class="cs-spinner"></span>' + esc(label || 'Working…');
        if (bar) bar.appendChild(badge);
        setStatus(label || 'Working…', true);
        try {
            return await work();
        } finally {
            badge.remove();
            setStatus('');
        }
    }


    async function openCharacterSheet(id) {
        SHEET = { id, character: null, gallery: [], costumes: [], filter: 'all' };
        document.getElementById('csName').textContent = 'Loading…';
        document.getElementById('csChips').innerHTML = '';
        document.getElementById('csBody').innerHTML = '<div class="text-muted" style="padding:40px;">Loading…</div>';
        showModal('characterSheetModal');
        await renderCharacterSheet();
    }

    /*
     * ── The location and prop sheets ────────────────────────────────────────
     *
     * Built from the region registries in lib/subject-sheets.js and held to
     * drawing every one, so a sheet cannot render the plates and silently drop
     * the continuity states — which looks finished in a screenshot.
     *
     * One shell, two renderers. The regions genuinely differ (a location has an
     * orientation and an hour; a prop has materials and a state) and pretending
     * otherwise would give both a compromise neither wanted — but the shell,
     * the busy spinner, the field writer and the export are shared, because
     * that is what came apart the last time a surface was built twice.
     */
    /*
     * The sheet's own state, plus the registries it renders FROM.
     *
     * The six description sections, the five official prop views and the hours
     * a location is kept at are declared in lib/subject-sheets.js and served —
     * mirroring them here is how a page and a library come to disagree about
     * what a sheet is made of.
     */
    const SS = {
        kind: null, id: null, data: null, views: [],
        sections: [], propViews: [], times: [], collapsed: {},
        parse(text, fallback) {
            if (text && typeof text === 'object') return text;
            try { const v = JSON.parse(text); return v == null ? fallback : v; } catch (_) { return fallback; }
        },
        // Mirrors parseList in lib/subject-sheets.js: a list column, or the
        // paragraph it replaced split into lines, so nothing typed is lost.
        list(json, legacy) {
            const v = SS.parse(json, null);
            if (Array.isArray(v) && v.length) return v.map(x => String(x).trim()).filter(Boolean);
            return String(legacy || '').split(/\n|;/).map(x => x.trim()).filter(Boolean);
        },
        materials(json, legacy) {
            const v = SS.parse(json, null);
            if (Array.isArray(v) && v.length) return v.filter(m => m && m.name);
            return String(legacy || '').split(/[,;\n]/).map(x => x.trim()).filter(Boolean)
                .map(name => ({ name, role: '', hex: '' }));
        },
    };

    async function openSubjectSheet(kind, id) {
        SS.kind = kind; SS.id = id; SS.data = null; SS.views = [];
        document.getElementById('ssName').textContent = 'Loading…';
        document.getElementById('ssChips').innerHTML = '';
        document.getElementById('ssBody').innerHTML = '<div class="text-muted">Loading…</div>';
        showModal('subjectSheetModal');
        await renderSubjectSheet();
    }

    /** Any spinner on the sheet. Clears in a finally, or it lies about working. */
    async function ssBusy(label, work) {
        const bar = document.getElementById('ssChips');
        const badge = document.createElement('span');
        badge.className = 'cs-chip cs-busy';
        badge.innerHTML = '<span class="cs-spinner"></span>' + esc(label || 'Working…');
        if (bar) bar.appendChild(badge);
        setStatus(label || 'Working…', true);
        try { return await work(); } finally { badge.remove(); }
    }

    async function renderSubjectSheet() {
        const body = document.getElementById('ssBody');
        if (!body || !SS.id) return;
        try {
            const plural = SS.kind + 's';
            const [subject, views, vocab, spec] = await Promise.all([
                api(`/${plural}/${SS.id}`),
                api(`/${plural}/${SS.id}/plate/views`).catch(() => ({ views: [] })),
                /*
                 * The categories the DATABASE will accept.
                 *
                 * The picker fell back to ['', whatever this prop already is],
                 * so it offered one option and a director could not change the
                 * category at all — the same "a picker must not offer what the
                 * database refuses" rule, failing from the other side by
                 * offering almost nothing. Served from the CHECK's own list.
                 */
                SS.kind === 'prop'
                    ? api('/card-vocabulary').catch(() => ({ prop_categories: [] }))
                    : Promise.resolve(null),
                // The registries the sheet is BUILT from, served rather than
                // mirrored: six sections and five views typed into the page go
                // stale the first time one is renamed.
                api('/sheet-spec').catch(() => null),
            ]);
            if (vocab && vocab.prop_categories) window.__propCategories = ['', ...vocab.prop_categories];
            if (spec) {
                SS.sections = spec.description_sections || [];
                SS.propViews = spec.prop_views || [];
                SS.times = spec.time_variants || [];
            }
            SS.data = subject[SS.kind] || subject;
            SS.views = views.views || [];
            document.getElementById('ssName').textContent = (SS.data.name || SS.kind).toUpperCase();
            document.getElementById('ssGenerateBtn').textContent =
                SS.kind === 'location' ? 'Generate plate' : 'Generate view';
            body.innerHTML = SS.kind === 'location' ? renderLocationSheet() : renderPropSheet();
        } catch (err) {
            // A renderer that paints a placeholder must have a path that
            // replaces it — a spinner that never resolves reads as the data
            // being gone rather than as a display fault.
            body.innerHTML = `<div class="empty-state"><h3>Could not open the sheet</h3>
                <p>${esc(err.message)}</p></div>`;
        }
    }

    /* ── shared pieces ─────────────────────────────────────────────────── */

    /*
     * `reach` is HTML and arrives as its own argument.
     *
     * It was concatenated into the title, which ssSection escapes — so every
     * "→ prompt" and "not sent" mark rendered as literal `<span …>` text. The
     * marks are the whole difference between a sheet and a form, so they get a
     * parameter rather than being smuggled through a field that is escaped.
     */
    function ssSection(anchorId, title, what, inner, reach) {
        return `<section class="ss-region" data-region="${anchorId}">
            <div class="ss-region-head">
                <h4>${esc(title)}${reach || ''}</h4>
                ${what ? `<p class="ss-what">${esc(what)}</p>` : ''}
            </div>
            ${inner}
        </section>`;
    }

    /**
     * VIEW MODE / EDIT MODE.
     *
     * The reference sheets are a READ-ONLY document: a director opens one to
     * look at it, and a page of input boxes is a form, not a sheet. So a sheet
     * opens in view mode and an EDIT button at the top right — not in the
     * design, added because the design has no way to change anything — turns
     * the fields on.
     *
     * NO LAYOUT SHIFT, which is the acceptance bar. The same element is used in
     * both modes and only `readonly` and a border change: swapping an input for
     * a paragraph would reflow the whole column on every toggle, and the eye
     * reads that as the sheet breaking.
     *
     * PICTURES ARE NOT PART OF THE MODE. Uploading and generating stay
     * available in both, because looking at a sheet is exactly when you notice
     * a plate is wrong — locking them away in view mode would take the controls
     * you use most while reading.
     */
    let SHEET_MODE = 'view';
    function sheetEditable() { return SHEET_MODE === 'edit'; }

    /** The button says what pressing it will DO next, on both sheets. */
    function paintSheetModeButtons() {
        const label = sheetEditable() ? 'Done' : 'Edit';
        ['csModeBtn', 'ssModeBtn'].forEach(id => {
            const b = document.getElementById(id);
            if (b) b.textContent = label;
        });
    }

    function toggleSheetMode() {
        SHEET_MODE = SHEET_MODE === 'view' ? 'edit' : 'view';
        paintSheetModeButtons();
        // Re-render whichever sheet is open; both keep their scroll position
        // because the box each field occupies does not change.
        const cs = document.getElementById('characterSheetModal');
        const ss = document.getElementById('subjectSheetModal');
        if (cs && cs.classList.contains('open')) renderCharacterSheet();
        else if (ss && ss.classList.contains('open')) renderSubjectSheet();
    }

    /** A field a director types straight into. Saved on blur, never on a timer. */
    function ssField(field, value, opts) {
        const o = opts || {};
        /*
         * `readonly` rather than a different element: the box stays exactly the
         * same size, so leaving edit mode moves nothing on the page.
         */
        const ro = sheetEditable() ? '' : ' readonly tabindex="-1"';
        const view = sheetEditable() ? '' : ' ss-view';
        const common = `data-field="${field}" onchange="saveSheetField('${field}', this.value, this)"`;
        if (o.rows) {
            return `<textarea class="ss-input${view}" rows="${o.rows}" placeholder="${esc(o.placeholder || '')}"${ro} ${common}>${esc(value || '')}</textarea>`;
        }
        if (o.options) {
            return `<select class="ss-input${view}"${sheetEditable() ? '' : ' disabled'} ${common}>${
                o.options.map(v => `<option value="${esc(v)}"${String(value || '') === v ? ' selected' : ''}>${esc(v || '—')}</option>`).join('')
            }</select>`;
        }
        return `<input class="ss-input${view}" type="${o.type || 'text'}"${o.step ? ` step="${o.step}"` : ''}${ro}
            placeholder="${esc(o.placeholder || '')}" value="${esc(value == null ? '' : String(value))}" ${common}>`;
    }


    function ssPlateControls() {
        /*
         * The target is written as a LITERAL per kind rather than computed.
         *
         * The media-import contract is derived from the registered targets and
         * is checked by looking for the call — a computed target is invisible
         * to it, and an import nothing checks is one that quietly stops
         * working. Two lines rather than a ternary inside the call, for that.
         */
        const opts = { extra: {}, after: 'renderSubjectSheet',
            title: 'Use a picture you already have — a photograph, a render, art you were handed' };
        const upload = SS.kind === 'location'
            ? uploadControl('location-plate', `/locations/${SS.id}/plate/import`, opts)
            : uploadControl('prop-plate', `/props/${SS.id}/plate/import`, opts);
        return `<div class="btn-row" style="margin-top:8px;">
            <button class="btn btn-secondary btn-sm" onclick="${SS.kind === 'location'
                ? `generateLocationPlateFor('${SS.id}')` : `generatePropPlateFor('${SS.id}')`}">Generate</button>
            ${/*
                The SAME upload control the cards used, not a second one — it
                carries the registered import target that the media-import
                contract is derived from, and a bespoke input beside it is how
                one of the two stops being checked.
              */ ''}
            ${upload}
            <button class="btn btn-secondary btn-sm" onclick="openSubjectGallery()">Gallery</button>
        </div>`;
    }

    /* ── pieces both sheets use ────────────────────────────────────────── */

    /* The design marks what reaches the generator and what does not, four
       different ways. That distinction is the whole difference between a sheet
       and a form, so it is rendered rather than remembered. */
    const ssReach = kind => kind === 'not-sent'
        ? '<span class="ss-reach ss-not-sent">not sent</span>'
        : '<span class="ss-reach">&rarr; prompt</span>';

    function ssChips(list) {
        return `<div class="cs-chips">${list.filter(Boolean).map(c =>
            `<span class="cs-chip ${c.cls || ''}">${c.html || esc(c.text)}</span>`).join('')}</div>`;
    }

    /** One reference tile, with the star that means "this conditions a frame". */
    function ssRefs() {
        const gallery = (SS.data && SS.data.gallery) || [];
        const cats = {};
        gallery.forEach(g => {
            const c = (g.category || g.role || 'other');
            cats[c] = (cats[c] || 0) + 1;
        });
        const filters = `<div class="ss-ref-filters">
            <span class="ss-ref-filter on">All ${gallery.length}</span>
            ${Object.entries(cats).map(([c, n]) =>
                `<span class="ss-ref-filter">${esc(c)} ${n}</span>`).join('')}
        </div>
        <p class="ss-what">starred refs are attached to the prompt</p>`;
        const tiles = gallery.length
            ? `<div class="cs-refs">${gallery.slice(0, 12).map(g => {
                const sent = g.role === 'reference';
                return `<figure class="cs-tile">
                    ${g.image_url ? `<img src="${esc(plateSrc(g.image_url, 320))}" alt="">` : '<div class="cs-drop"></div>'}
                    <figcaption>${sent ? '<span class="ss-ref-star">&#9733;</span> ' : ''}${esc(g.note || g.role || '')}</figcaption>
                </figure>`;
            }).join('')}</div>`
            : '<p class="text-muted">Nothing gathered yet.</p>';
        return filters + tiles
            + `<button class="btn btn-secondary btn-sm" style="margin-top:8px;" onclick="openSubjectGallery()">+ Drop reference</button>`;
    }

    /** The provenance the design prints under the plates. */
    /**
     * What this plate IS: seed where one was recorded, size, and the REAL
     * format.
     *
     * It fell back to the literal 'png' and so reported a JPEG plate as a PNG
     * -- the asset row said `format: jpg, mime_type: image/jpeg` and the file
     * on disk ended `.jpg`. Nothing shows a format we were not told; an
     * unknown one is simply omitted rather than guessed, because a confident
     * wrong answer here is worse than a shorter line.
     *
     * A space-between row, as the design draws it: what made the picture on
     * the left, what the file is on the right.
     */
    function ssPlateMeta() {
        const v = (SS.views || []).find(x => x.available) || null;
        if (!v) return '';
        const kb = v.bytes ? `${Math.round(v.bytes / 1024)} kB` : '';
        const left = [v.seed ? `seed ${esc(String(v.seed))}` : '', v.set ? esc(v.set) : '']
            .filter(Boolean).join(' — ');
        const right = [v.format ? esc(String(v.format)) : '', kb].filter(Boolean).join(' · ');
        if (!left && !right) return '';
        return `<p class="ss-plate-meta"><span>${left}</span><span>${right}</span></p>`;
    }

    /*
     * Which plate fills a slot.
     *
     * A slot that names no view means the DEFAULT plate — the view-less one
     * every location has had since before views existed. Matching the slot's
     * role instead left the master plate out of its own slot and the sheet
     * reported "Plates locked 0/1" for a location with two.
     */
    const ssViewFor = name => {
        const want = String(name || '').trim().toLowerCase();
        const views = SS.views || [];
        const bare = views.find(v => !String(v.view || '').trim());
        if (!want) return bare || views[0] || null;
        const named = views.find(v => String(v.view || '').trim().toLowerCase() === want);
        if (named) return named;
        /*
         * A view-less plate IS the front.
         *
         * Every plate generated before views existed carries no view name, and
         * lib/plate-views.js ranks front first for exactly this reason — it is
         * the identity plate, the one headlinePlate attaches to a shot. Without
         * this the turntable reported "locked 1/5" with the front slot showing
         * "generate →" for a prop whose plate is sitting right there.
         */
        return (SS.kind === 'prop' && want === 'front') ? bare || null : null;
    };

    /**
     * One plate tile.
     *
     * `shape` names the sheet's own plate class, because a plate is the shape
     * of its SUBJECT: a location is landscape, a prop is square, a character is
     * a portrait turnaround. All three used to share the character's grid,
     * which showed a location in a portrait crop — the wrong picture of the
     * right place, which is what a plate exists to prevent.
     */
    /**
     * Upload a picture INTO ONE SLOT.
     *
     * The routes have always taken `body.view`, so a particular view has been
     * uploadable since plate uploads shipped -- what the page offered was one
     * Upload per subject, which fills the DEFAULT plate. On a sheet that draws
     * its plates as numbered slots that is the wrong picture: the only way to
     * fill 02 or the side view was to buy it, while the photograph the director
     * already had could only be dropped on the subject as a whole.
     */
    function slotUpload(kind, subjectId, view, label) {
        const target = kind === 'character' ? 'character-plate'
            : kind === 'location' ? 'location-plate' : 'prop-plate';
        const url = kind === 'character'
            ? `/characters/${subjectId}/refsheet/import`
            : `/${kind}s/${subjectId}/plate/import`;
        return uploadControl(target, url, {
            label: label || 'upload',
            title: 'Use a picture you already have for this view',
            extra: view ? { view: view } : {},
        });
    }

    function ssTile(v, label, caption, shape) {
        const url = v && v.available && v.image_url ? API_BASE + v.image_url : '';
        const cls = shape || 'cs-tile';
        /*
         * The number and the affordance are drawn INSIDE the tile, over the
         * picture -- the label top-left, `generate ->` bottom-left -- because
         * that is what the design draws and what the character sheet has always
         * done. Rendered beneath in a <figcaption>, with `generate ->` centred
         * in the empty box, a plate reads as a captioned photograph and the
         * sheet reads as unfinished, which is how it was reported three times.
         *
         * The caption (what the view IS) stays below: it is prose about the
         * plate rather than a marker on it, and laid over the picture it would
         * compete with the number.
         */
        return `<figure class="ss-slot" style="margin:0;">
            <div class="${cls}">
            ${url ? `<img src="${esc(url)}" alt="${esc(label)}" onclick="openPlateViewer('${esc(url)}', ${jsAttr(label)})">`
                  : `<div class="cs-drop ss-empty" style="width:100%;height:100%;"></div>`}
            <span class="ss-num">${esc(label)}</span>
            ${url ? '' : `<span class="ss-gen" onclick="generateSheetView(${jsAttr((v && v.view) || label)})">generate &rarr;</span>
                <span class="ss-up" onclick="event.stopPropagation();">${
                    slotUpload(SS.kind, SS.id, (v && v.view) || '', 'upload')}</span>`}
            </div>
            ${caption ? `<figcaption class="ss-slot-caption"><span class="ss-view-angle">${esc(caption)}</span></figcaption>` : ''}
        </figure>`;
    }

    /* ── location ──────────────────────────────────────────────────────── */

    /*
     * THE DIAGRAM IS A DIAGRAM, AND THE FIELD BEHIND IT IS PROSE.
     *
     * The compass grid draws its edges as labels -- east and west vertically,
     * in 62px gutters -- so it was built assuming "harbour window + door" and
     * the store capped every edge at 200 characters to keep that true. But
     * this field is what buildPlatePrompt now reads to generate each side, so
     * it has to be able to say what is on that side at length. The store
     * keeps the whole text; the diagram shows the head of it, hovering shows
     * the rest, and the editor has all of it.
     */
    function ssPlanLabel(text, max = 46) {
        const s = String(text || '').trim();
        if (!s) return '—';
        if (s.length <= max) return s;
        // Cut on a word, and prefer a clause end if there is one in range.
        const head = s.slice(0, max);
        const stop = Math.max(head.lastIndexOf(' — '), head.lastIndexOf(', '), head.lastIndexOf('. '));
        const cut = stop > max * 0.5 ? head.slice(0, stop) : head.slice(0, head.lastIndexOf(' ') + 1 || max);
        return cut.replace(/[\s,.;:—-]+$/, '') + '…';
    }

    function renderLocationSheet() {
        const l = SS.data || {};
        const S = SS.sections;
        const sections = SS.parse(l.description_sections, {});
        const flags = SS.list(l.continuity_flags, l.continuity_notes);
        const plan = SS.parse(l.orientation_plan, {});
        const planned = SS.parse(l.plate_plan, []);
        /*
         * FOUR SLOTS, as the design draws them -- its own badge reads "Plates
         * locked 3/4". A location that has never been planned is the common
         * case and was rendering the hero ALONE, because the 3-up row is only
         * emitted when there is more than one slot. The roles are the generic
         * coverage a location needs; the design's own names (Reverse, Counter,
         * Exterior) are one diner's content, so only the structure is copied.
         */
        const slots = planned.length ? planned : [
            { n: 1, role: 'Master', view: '', caption: 'the establishing plate' },
            { n: 2, role: 'Reverse', view: 'south', caption: 'the opposite side' },
            { n: 3, role: 'Detail', view: 'east', caption: 'a closer read of one part' },
            { n: 4, role: 'Exterior', view: 'west', caption: 'how it sits in its surroundings' },
        ];
        const made = slots.filter(x => ssViewFor(x.view)).length;
        const total = Object.values(sections).join(' ').length;
        const linked = l.linked_props || [];

        document.getElementById('ssChips').innerHTML = ssChips([
            { text: `${String(l.id || '').slice(0, 8)} · ${l.location_type || 'int/ext'}`, cls: 'ss-chip-id' },
            { text: `Plates locked ${made}/${slots.length}`, cls: 'ss-chip-plates' },
            { text: `Used in ${Number(l.scene_count) || 0} scenes`, cls: 'ss-chip-scenes' },
            flags.length ? { text: `Continuity: ${flags.length} flag(s)`, cls: 'ss-chip-flags' } : null,
        ]);

        return `
        <div class="ss-grid ls-grid">
          <div class="ss-col">
            ${ssSection('ls-plates', 'Master plates', 'canonical · fed to generation',
                /*
                 * The establishing plate leads, full width. It is not one of
                 * four — it is the one every shot in the scene is
                 * re-photographed against, and the design gives it its own
                 * block above the others for that reason.
                 */
                `<div class="ls-plates-hero">${
                    ssTile(ssViewFor(slots[0].view),
                        `${String(slots[0].n).padStart(2, '0')} · ${slots[0].role}`,
                        slots[0].caption, 'ls-plate')}</div>
                 ${slots.length > 1 ? `<div class="ls-plates-rest">${slots.slice(1).map(sl =>
                    ssTile(ssViewFor(sl.view), `${String(sl.n).padStart(2, '0')} · ${sl.role}`,
                        sl.caption, 'ls-plate')
                 ).join('')}</div>` : ''}${ssPlateMeta()}${ssPlateControls()}
                 <button class="btn btn-secondary btn-sm" style="margin-top:6px;" onclick="ssEditPlatePlan()">Plan the views</button>`)}

            ${ssSection('ls-orientation', 'Orientation plan', 'keeps geography consistent across plates',
                `<div class="ss-plan">${l.orientation_plan_image_url ? `<img class="ss-plan-image" src="${esc(API_BASE + l.orientation_plan_image_url)}"
                    alt="Orientation plan for ${esc(l.name || 'location')}"
                    onclick="openPlateViewer('${esc(API_BASE + l.orientation_plan_image_url)}', ${jsAttr((l.name || 'Location') + ' — orientation plan')})">` : ''}
                 <div class="ss-plan-grid">
                    <span></span><span class="ss-plan-edge n" title="${esc(plan.north || '')}">North · ${esc(ssPlanLabel(plan.north))}</span><span></span>
                    <span class="ss-plan-edge w" title="${esc(plan.west || '')}">West · ${esc(ssPlanLabel(plan.west))}</span>
                    <div class="ss-plan-room">${[0,1,2].map((_, i) =>
                        `<span class="ss-plan-zone" title="${esc((plan.interior || [])[i] || '')}">${esc(ssPlanLabel((plan.interior || [])[i]))}</span>`).join('')}</div>
                    <span class="ss-plan-edge e" title="${esc(plan.east || '')}">East · ${esc(ssPlanLabel(plan.east))}</span>
                    <span></span><span class="ss-plan-edge s" title="${esc(plan.south || '')}">South · ${esc(ssPlanLabel(plan.south))}</span><span></span>
                 </div>${plan.marker ? `<p class="ss-plan-marker" title="${esc(plan.marker)}">&#9650; ${esc(ssPlanLabel(plan.marker, 160))}</p>` : ''}</div>
                 <div class="btn-row" style="margin-top:8px;">
                   <button class="btn btn-secondary btn-sm" onclick="ssEditPlan()">Edit the plan</button>
                   ${uploadControl('orientation-plan', `/locations/${SS.id}/orientation-plan/import`, {
                       extra: {}, after: 'renderSubjectSheet', title: 'Upload an LLM-generated orientation plan image'
                   })}
                   ${l.orientation_plan_image_url ? `<button class="btn btn-secondary btn-sm" onclick="ssDeletePlanImage()">Remove image</button>` : ''}
                   ${captureUploadControl(SS.id, { after: 'renderSubjectSheet' })}
                 </div>`)}

            ${ssSection('ls-variants', 'Time of day variants',
                'The same place at another hour, kept as its own plate rather than regraded.',
                `<div class="ss-variants">${SS.times.map(t => {
                    const have = ssViewFor(t);
                    return `<span class="ss-variant${have ? ' on' : ''}" onclick="generateLocationVariant('${t}')">${t}${have ? ' &#10003;' : ''}</span>`;
                }).join('')}</div>`)}

            

            
          </div>

          <div class="ss-col">
            ${ssSection('ls-description', 'Set description',
                '', `<p class="ss-what ss-desc-total">${total} chars · ${S.length} sections · prompt source ${ssReach('prompt')}</p>` +
                `<div class="btn-row" style="margin-bottom:8px;">
                    <button class="btn btn-secondary btn-sm" onclick="ssCopyDescription()">Copy all</button>
                    <button class="btn btn-secondary btn-sm" onclick="ssToggleSection('*')">Collapse all</button>
                 </div>
                 ${(!Object.keys(sections).length && String(l.description || '').trim())
                    ? `<div class="ss-import">
                        <p>This location was described before the sections existed
                        (${String(l.description).trim().length} characters). Move it into a section to keep it —
                        nothing is written until you choose.</p>
                        <div class="btn-row">${S.map(sec =>
                            `<button class="btn btn-secondary btn-sm" onclick="ssImportDescription('${sec.id}')">${esc(sec.label)}</button>`).join('')}</div>
                       </div>`
                    : ''}
                 ${S.map(sec => {
                    const text = sections[sec.id] || '';
                    return `<div class="ss-section" data-section="${sec.id}">
                        <div class="ss-section-head" onclick="ssToggleSection('${sec.id}')">
                            <span class="ss-section-label">${esc(sec.label)}</span>
                            <span class="ss-section-meta">${esc(sec.kind)} · ${text.length} chars</span>
                        </div>
                        <div class="ss-section-body">
                            <p class="ss-what">${esc(sec.what)}</p>
                            <textarea class="ss-input${sheetEditable() ? '' : ' ss-view'}" rows="4"
                                data-field="section_${sec.id}"${sheetEditable() ? '' : ' readonly tabindex="-1"'}
                                onchange="saveSheetSection('${sec.id}', this.value, this)">${esc(text)}</textarea>
                            ${sec.id === 'decoration' ? `<div class="ss-linked">${
                                linked.map(pr => `<span class="ss-linked-prop" onclick="openSubjectSheet('prop','${pr.id}')">${esc(pr.name)}</span>`).join('')
                                || '<span class="text-muted">No prop named here exists yet.</span>'
                            }</div>` : ''}
                        </div>
                    </div>`;
                 }).join('')}`)}

            <div class="ls-support-grid">
            ${ssSection('ls-lighting', 'Lighting default',
                'How it is lit unless a shot says otherwise.',
                ssField('lighting_default', l.lighting_default, { placeholder: 'golden-hour rake off the water, lit practicals' })
                + ssField('lighting_technique', l.lighting_technique, { options: [''].concat(LIGHTING_TECHNIQUE_IDS) })
                + ssField('lighting_key_side', l.lighting_key_side, { options: ['', 'right', 'left'] })
                + ssField('time_of_day_default', l.time_of_day_default, { placeholder: 'late afternoon' })
                + ssField('location_type', l.location_type, { options: ['', 'interior', 'exterior', 'practical', 'stage', 'backlot'] }),
                ssReach('prompt'))}

            ${ssSection('ls-atmosphere', 'Atmosphere',
                'Weather, haze, season — the standing conditions of the place.',
                ssField('atmosphere_notes', l.atmosphere_notes, { rows: 2, placeholder: 'immaculate, gleaming, air still' }),
                ssReach('prompt'))}

            ${ssSection('ls-sound', 'Sound notes',
                'Notes for whoever writes the ambient cue. This does not reach the image prompt.',
                ssField('sound_notes', l.sound_notes, { rows: 2, placeholder: 'gulls, a screen door, radio low behind the counter' }),
                ssReach('not-sent'))}
            </div>

            
          </div>
        </div>

        <!--
            THE FOOTER, full width beneath the two-column body.

            The design puts Concept art & references in a 1fr column with
            Scenes here and Continuity flags in a 300px one, BELOW the body
            rather than inside it (minmax(0,1fr) 300px, handoff line 236).
            Kept in the body, the references were pinned to half the card and
            the 300px column existed nowhere on the sheet.
        -->
        <div class="ls-footer">
          <div class="ss-col">
            ${ssSection('ls-references', 'Concept art & references',
                'Explorations and gathered images.', ssRefs())}
          </div>
          <div class="ss-col">
            ${ssSection('ls-scenes', 'Scenes here',
                'Derived from the scene headings that name this location.',
                (l.scenes || []).length
                    ? (l.scenes || []).map(sc => {
                        const hour = String(sc.time_of_day || '').toLowerCase();
                        const covered = !hour || ssViewFor(hour);
                        return `<div class="ss-scene-row">
                            <span>Sc. ${esc(String(sc.scene_number))}</span>
                            <span class="text-muted">${esc(sc.time_of_day || '')}${covered ? '' : ' · no plate'}</span>
                        </div>`;
                    }).join('')
                    : '<p class="text-muted">No scene here yet.</p>')}
            ${ssSection('ls-continuity', 'Continuity flags',
                'What must stay true in EVERY plate.',
                `<div>${flags.map((f, i) => `<div class="ss-flag">
                    <span>${esc(f)}</span>
                    <button class="btn btn-secondary btn-sm" onclick="ssRemoveFlag(${i})">&times;</button>
                 </div>`).join('') || '<p class="text-muted">Nothing to hold yet.</p>'}</div>
                 <button class="btn btn-secondary btn-sm" style="margin-top:8px;" onclick="ssAddFlag()">Add flag</button>`)}
          </div>
        </div>`;
    }

    /* ── prop ──────────────────────────────────────────────────────────── */

    /*
     * VIEWS THAT ARE NOT ON THE TURNTABLE ARE STILL PICTURES.
     *
     * The turntable renders the five canonical slots and matches each by exact
     * name, so a plate generated as "rear", "three-quarter rear" or "interior"
     * was filed, paid for, sitting on disk -- and rendered NOWHERE. The sheet
     * showed one tile and looked like the generation had failed.
     *
     * A canonical set is right: which angles a turnaround needs is a fact about
     * turnarounds. But it cannot be the only thing the sheet can display, or the
     * naming of a view silently decides whether the director ever sees it.
     */
    function psExtraViews() {
        const canonical = new Set((SS.propViews || []).map(v => String(v.id).toLowerCase()));
        const extra = (SS.views || []).filter(v => {
            const name = String(v.view || '').trim();
            return name && !canonical.has(name.toLowerCase());
        });
        if (!extra.length) return '';
        return ssSection('ps-extra-views', 'Other views', 'off the turntable · still fed to generation',
            `<div class="ps-plates">${extra.map(v =>
                ssTile(v, v.view, 'named view · not one of the five', 'ps-plate')).join('')}</div>
             <p class="ss-note">Generated under a name the turntable does not carry. Rename or regenerate
             it as one of the five to have it count towards "locked".</p>`);
    }

    function renderPropSheet() {
        const p = SS.data || {};
        const states = SS.parse(p.continuity_states, []);
        const materials = SS.materials(p.materials_json, p.materials);
        const constraints = SS.list(p.constraints_json, p.constraints);
        const keywords = SS.list(p.keywords, '');
        /*
         * LOCKED COUNTS THE TURNTABLE, NOT EVERY PICTURE.
         *
         * It counted PICTURES and asked which were canonical. A subject can
         * hold two pictures for one slot — a view-less plate is the identity
         * plate and reads as `front`, while an explicit `front` view may also
         * exist — so one slot counted twice. Measured on the live install:
         * 9 views, 6 counted, 5 slots actually filled, front counted twice.
         *
         * Restricting the count to canonical names was the first attempt and
         * still returned 6/5, because both of those rows genuinely ARE front.
         * Only counting SLOTS can be bounded by the number of slots, which is
         * the shape the location and character sheets already had — and why
         * neither of them could ever print this.
         */
        const slotFilled = (id) => (SS.views || []).some(v =>
            v.available && String(v.view || 'front').trim().toLowerCase() === String(id).toLowerCase());
        const made = (SS.propViews || []).filter(slot => slotFilled(slot.id)).length;
        const mm = v => (Number(v) > 0 ? `${Math.round(Number(v) * 1000)} mm` : '—');
        const biggest = Math.max(Number(p.height_m) || 0, Number(p.width_m) || 0, Number(p.length_m) || 0);
        const verdict = !biggest ? 'size not declared'
            : biggest < 0.12 ? 'one-hand object' : biggest < 0.6 ? 'two-hand object'
            : biggest < 2 ? 'carried with effort' : 'set piece';

        document.getElementById('ssChips').innerHTML = ssChips([
            { text: `${String(p.id || '').slice(0, 8)} · ${p.category || 'generic'}`, cls: 'ss-chip-id' },
            { text: `Turntable locked ${made}/${SS.propViews.length}`, cls: 'ss-chip-plates' },
            { text: p.practical ? 'Handled on camera' : 'Not handled', cls: 'ss-chip-handled' },
            { text: `${states.length || 1} state(s)`, cls: 'ss-chip-states' },
        ]);

        return `
        <div class="ps-turntable">
            ${ssSection('ps-plates', 'Turntable · official views', 'canonical · fed to generation',
                /*
                 * Square, auto-fitting, as the prop design lays it out. A prop
                 * is photographed filling its own frame from every side, so
                 * five equal square views ARE the turntable — there is no hero
                 * among them the way a location has an establishing plate.
                 */
                `<div class="ps-plates">${SS.propViews.map(v =>
                    ssTile(ssViewFor(v.id), v.label, `${v.angle} · ${v.caption}`, 'ps-plate')).join('')}</div>
                 ${ssPlateMeta()}${ssPlateControls()}`)}
            ${psExtraViews()}
        </div>

        <div class="ss-grid ps-grid">
          <div class="ss-col">
            ${ssSection('ps-description', 'Object description',
                `${String(p.visual_prompt || '').length} chars · prompt source`,
                `<button class="btn btn-secondary btn-sm" style="margin-bottom:8px;" onclick="ssCopyDescription()">Copy</button>`
                + ssField('visual_prompt', p.visual_prompt, { rows: 5, placeholder: 'Chrome-and-amber tabletop jukebox selector, bolted at seated height…' })
                + `<div class="ss-keywords">${keywords.map((k, i) =>
                    `<span class="ss-keyword" onclick="ssRemoveKeyword(${i})">${esc(k)} &times;</span>`).join('')}
                   <span class="ss-keyword ss-add" onclick="ssAddKeyword()">+ keyword</span></div>
                   <p class="ss-what">The few words that must survive into every frame.</p>`
                + '<p class="ss-what">For a person; reaches no prompt.</p>'
                + ssField('description', p.description, { rows: 2, placeholder: 'A tabletop jukebox selector, one per booth.' }),
                ssReach('prompt'))}

            ${ssSection('ps-materials', 'Materials & finish', 'What it is made of and how it catches light.',
                `<div>${materials.map((m, i) => `<div class="ss-material">
                    <span class="ss-mat-swatch" style="background:${/^#[0-9A-F]{6}$/i.test(m.hex) ? m.hex : 'transparent'};"></span>
                    <strong>${esc(m.name)}</strong>
                    <span class="text-sm text-muted">${esc(m.role || '')}${m.hex ? ' · ' + esc(m.hex) : ''}</span>
                    <button class="btn btn-secondary btn-sm" onclick="ssRemoveMaterial(${i})">&times;</button>
                 </div>`).join('') || '<p class="text-muted">Nothing recorded.</p>'}</div>
                 <button class="btn btn-secondary btn-sm" style="margin-top:8px;" onclick="ssAddMaterial()">Add material</button>`)}

            ${ssSection('ps-states', 'Continuity states', 'each state generates its own plate set',
                `<div class="ps-states-grid">${states.length ? states.map((st, i) => `<div class="ss-state">
                    <strong>${String.fromCharCode(65 + i)} · ${esc(st.name)}</strong>
                    ${st.scene ? `<span class="cs-pill">${esc(st.scene)}</span>` : '<span class="cs-pill">default</span>'}
                    <span class="text-sm text-muted">${esc(st.what || '')}</span>
                    <button class="btn btn-secondary btn-sm" onclick="removePropState(${i})">&times;</button>
                 </div>`).join('') : '<p class="text-muted">One state — as built. Add another when it changes.</p>'}</div>
                 <button class="btn btn-secondary btn-sm" style="margin-top:8px;" onclick="addPropState()">Add state</button>`)}

            ${ssSection('ps-references', 'Concept art & references',
                'Explorations and gathered images.', ssRefs())}
          </div>

          <div class="ss-col">
            ${ssSection('ps-scale', 'Scale',
                'How big it is. Without this an image model reproduces whatever it was shown, at any size.',
                `<div class="ss-scale-bar">
                    <span class="ss-scale-hand">hand</span>
                    <span class="ss-scale-prop" style="width:${Math.max(8, Math.min(100, (biggest || 0) * 120))}%;">prop</span>
                 </div>
                 <p class="cs-prose">W ${mm(p.width_m)} · H ${mm(p.height_m)} · D ${mm(p.length_m)} &mdash; ${verdict}</p>
                 <div class="ss-spec-grid">
                    <label>Height (m) ${ssField('height_m', p.height_m, { type: 'number', step: '0.01' })}</label>
                    <label>Width (m) ${ssField('width_m', p.width_m, { type: 'number', step: '0.01' })}</label>
                    <label>Length (m) ${ssField('length_m', p.length_m, { type: 'number', step: '0.01' })}</label>
                 </div>`)}

            ${ssSection('ps-spec', 'Spec', 'Period, category, how many there are, and whether it has to work on camera.',
                `<div class="ss-spec-row"><span>Period</span>${ssField('period', p.period, { placeholder: '1952' })}</div>
                 <div class="ss-spec-row"><span>Category</span>${ssField('category', p.category, { options: (window.__propCategories || ['', p.category || '']) })}</div>
                 <div class="ss-spec-row"><span>Quantity</span>${ssField('quantity', p.quantity == null ? 1 : p.quantity, { type: 'number' })}</div>
                 <div class="ss-spec-row"><span>Practical</span>${ssField('practical', p.practical ? 'yes' : 'no', { options: ['no', 'yes'] })}</div>`)}

            ${ssSection('ps-appears', 'Appears in',
                'From the scene cards that NAME this prop — the same list that decides whether its plate reaches a frame.',
                ((p.shots || []).length
                    ? (p.shots || []).map(code => `<div class="ss-appear-row">
                        <span>${esc(code)}</span>
                        <span class="text-muted">state ${states.length ? 'A' : '—'}</span>
                       </div>`).join('')
                    : '<p class="text-muted">No shot names it yet.</p>')
                + `<div class="ss-open-set">${(p.locations || []).slice(0, 6).map(loc =>
                    `<span class="ss-linked-prop" onclick="openSubjectSheet('location','${loc.id}')">Open set &rarr; ${esc(loc.name)}</span>`).join('')
                    || '<span class="text-muted">No set to open.</span>'}</div>`)}

            ${ssSection('ps-constraints', 'Constraints', 'What it must never be or do.',
                `<div>${constraints.map((c, i) => `<div class="ss-constraint">
                    <span>${esc(c)}</span>
                    <button class="btn btn-secondary btn-sm" onclick="ssRemoveConstraint(${i})">&times;</button>
                 </div>`).join('') || '<p class="text-muted">Nothing recorded.</p>'}</div>
                 <button class="btn btn-secondary btn-sm" style="margin-top:8px;" onclick="ssAddConstraint()">Add constraint</button>
                 <p class="ss-what">Production notes — for a person. These reach NO prompt.</p>
                 ${ssField('notes', p.notes, { rows: 2, placeholder: 'two built, one held back for the break' })}`)}
          </div>
        </div>`;
    }

    /* ── the ways in ───────────────────────────────────────────────────── */

    /* ── editing the structured half ───────────────────────────────────── */

    /** One description section. Merged, so writing one never clears another. */
    async function saveSheetSection(id, text, el) {
        const sections = { ...(SS.parse(SS.data.description_sections, {}) || {}), [id]: text };
        try {
            await api(`/locations/${SS.id}`, {
                method: 'PUT', body: JSON.stringify({ description_sections: sections }),
            });
            SS.data.description_sections = JSON.stringify(sections);
            if (el) el.style.borderColor = 'var(--gl-success, #166534)';
            // Redrawn so the character count and the total move with the text —
            // a count that does not is worse than none.
            renderSubjectSheet();
        } catch (err) {
            if (el) el.style.borderColor = 'var(--gl-danger, #7f1d1d)';
            setStatus('Error: ' + err.message);
        }
    }

    /**
     * Move an old one-paragraph description into a section.
     *
     * Every location written before the sections existed has its text in
     * `description`, and composing over it would replace an 856-character set
     * description with whatever was typed into one box. The route refuses that;
     * this is the way through — the director says WHICH section the old text
     * is, because only they know.
     */
    async function ssImportDescription(sectionId) {
        const text = String((SS.data && SS.data.description) || '').trim();
        if (!text) return;
        const sections = { ...(SS.parse(SS.data.description_sections, {}) || {}), [sectionId]: text };
        try {
            await api(`/locations/${SS.id}`, {
                method: 'PUT',
                // Deliberate: the old text is now IN the sections, so composing
                // over the column loses nothing.
                body: JSON.stringify({ description_sections: sections, replace_description: true }),
            });
            SS.data.description_sections = JSON.stringify(sections);
            await renderSubjectSheet();
            setStatus('Moved into the section. The description is now composed from the sections.');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /** Fold a section, or all of them. Six open at once is unreadable. */
    function ssToggleSection(id) {
        const all = id === '*';
        const nodes = document.querySelectorAll('#ssBody .ss-section');
        const anyOpen = [...nodes].some(n => !n.classList.contains('closed'));
        nodes.forEach(n => {
            if (all) n.classList.toggle('closed', anyOpen);
            else if (n.dataset.section === id) n.classList.toggle('closed');
        });
    }

    /** The whole description, assembled the way the prompt receives it. */
    function ssCopyDescription() {
        const text = SS.kind === 'prop'
            ? String((SS.data && SS.data.visual_prompt) || '')
            : SS.sections.map(sec => {
                const body = (SS.parse(SS.data.description_sections, {}) || {})[sec.id] || '';
                return body ? `${sec.label.toUpperCase()}\n${body}` : '';
            }).filter(Boolean).join('\n\n');
        if (!text) return setStatus('Nothing written yet.');
        navigator.clipboard.writeText(text)
            .then(() => setStatus(`${text.length} characters copied.`))
            .catch(() => setStatus('Could not reach the clipboard.'));
    }

    /** A generic list column: continuity flags, constraints, keywords. */
    async function ssSaveList(field, list) {
        const url = SS.kind === 'location' ? `/locations/${SS.id}` : `/props/${SS.id}`;
        try {
            await api(url, { method: 'PUT', body: JSON.stringify({ [field]: list }) });
            SS.data[field] = JSON.stringify(list);
            await renderSubjectSheet();
        } catch (err) { setStatus('Error: ' + err.message); }
    }
    const ssReadList = field => SS.list(SS.data[field],
        field === 'continuity_flags' ? SS.data.continuity_notes
            : field === 'constraints_json' ? SS.data.constraints : '');

    function ssAddFlag() {
        const v = prompt('What must stay true in every plate?');
        if (v && v.trim()) ssSaveList('continuity_flags', [...ssReadList('continuity_flags'), v.trim()]);
    }
    function ssRemoveFlag(i) {
        const list = ssReadList('continuity_flags'); list.splice(i, 1);
        ssSaveList('continuity_flags', list);
    }
    function ssAddConstraint() {
        const v = prompt('What must it never be or do?');
        if (v && v.trim()) ssSaveList('constraints_json', [...ssReadList('constraints_json'), v.trim()]);
    }
    function ssRemoveConstraint(i) {
        const list = ssReadList('constraints_json'); list.splice(i, 1);
        ssSaveList('constraints_json', list);
    }
    function ssAddKeyword() {
        const v = prompt('A word that must survive into every frame:');
        if (v && v.trim()) ssSaveList('keywords', [...SS.list(SS.data.keywords, ''), v.trim()]);
    }
    function ssRemoveKeyword(i) {
        const list = SS.list(SS.data.keywords, ''); list.splice(i, 1);
        ssSaveList('keywords', list);
    }

    /** A material row: what it is, where it is, and its colour. */
    async function ssAddMaterial() {
        const name = prompt('Material — "polished chrome", "amber acrylic"?');
        if (!name || !name.trim()) return;
        const role = prompt('Where is it, and how does it behave? — "panel, backlit"') || '';
        const hex = prompt('Its colour as #rrggbb (optional) — a hex nobody can see is a string') || '';
        const list = SS.materials(SS.data.materials_json, SS.data.materials);
        list.push({ name: name.trim(), role: role.trim(), hex: hex.trim() });
        await ssSaveList('materials_json', list);
    }
    async function ssRemoveMaterial(i) {
        const list = SS.materials(SS.data.materials_json, SS.data.materials);
        list.splice(i, 1);
        await ssSaveList('materials_json', list);
    }

    /**
     * The plan of the room.
     *
     * This is what keeps four plates of one place describing the same place —
     * a plate carries no information about what is behind its own camera, so
     * without the plan each side is generated from prose that cannot say.
     */
    async function ssEditPlan() {
        const plan = SS.parse(SS.data.orientation_plan, {}) || {};
        const next = { interior: plan.interior || [], marker: plan.marker || '' };
        for (const edge of ['north', 'east', 'south', 'west']) {
            const v = prompt(`${edge.toUpperCase()} — what is on that side?`, plan[edge] || '');
            if (v === null) return;
            next[edge] = v.trim();
        }
        const inside = prompt('Exactly three room zones, comma separated — "counter and stools, centre aisle, booths"',
            (plan.interior || []).join(', '));
        if (inside !== null) next.interior = inside.split(',').map(x => x.trim()).filter(Boolean).slice(0, 3);
        const marker = prompt('Where does the action sit? — "corner booth, north end"', plan.marker || '');
        if (marker !== null) next.marker = marker.trim();
        try {
            await api(`/locations/${SS.id}`, { method: 'PUT', body: JSON.stringify({ orientation_plan: next }) });
            SS.data.orientation_plan = JSON.stringify(next);
            await renderSubjectSheet();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function ssDeletePlanImage() {
        if (!confirm('Remove this orientation-plan image?\n\nThe scan moves to deleted/orientation so it can be recovered by hand. The structured compass plan stays.')) return;
        try {
            await api(`/locations/${SS.id}/orientation-plan`, { method: 'DELETE' });
            await renderSubjectSheet();
            setStatus('Orientation-plan image removed; compass data kept.');
        } catch (err) { setStatus('Could not remove the plan image: ' + err.message); }
    }

    /**
     * Which views this location is MEANT to have.
     *
     * An ungenerated view then shows as a labelled empty slot rather than an
     * absence nobody can see — which is the difference between "we still need
     * the reverse" and a sheet that looks finished.
     */
    async function ssEditPlatePlan() {
        const plan = SS.parse(SS.data.plate_plan, []) || [];
        const raw = prompt(
            'The views this location needs, one per line as "role | view name | caption".\n\n'
            + 'The view name is what a shot card asks for; leave it blank for the default plate.',
            (plan.length ? plan : [{ role: 'Master', view: '', caption: 'the establishing plate' }])
                .map(x => [x.role, x.view, x.caption].join(' | ')).join('\n'));
        if (raw === null) return;
        const next = raw.split('\n').map(line => {
            const [role, view, caption] = line.split('|').map(x => (x || '').trim());
            return { role, view, caption };
        }).filter(x => x.role);
        try {
            await api(`/locations/${SS.id}`, { method: 'PUT', body: JSON.stringify({ plate_plan: next }) });
            SS.data.plate_plan = JSON.stringify(next);
            await renderSubjectSheet();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /** Generate one named view — a planned slot, or an official prop view. */
    /**
     * Generate one view from a subject sheet.
     *
     * DELEGATES to regeneratePlate, which already carries the free preview, the
     * editable prompt and the provider/model/quality/size controls. This used
     * to send a bare confirm() and then POST to `/props/${SS.id}/plate/generate`
     * for anything that was not a location -- so pressing Generate on a
     * CHARACTER sheet posted a character's id to the props endpoint, and
     * nothing happened. Reported as exactly that: "no prompt was shown,
     * nothing, not even a spinner".
     */
    async function generateSheetView(view) {
        if (!SS.id || !SS.kind) return;
        return regeneratePlate(SS.kind, SS.id, view, () => renderSubjectSheet());
    }

    /**
     * Write one field.
     *
     * Merged by the route, so typing in one box cannot clear another — the
     * lesson the scene card and the provider config both paid for.
     */
    async function saveSheetField(field, value, el) {
        if (!SS.id) return;
        let v = value;
        if (field === 'practical') v = value === 'yes';
        if (['quantity', 'height_m', 'width_m', 'length_m'].includes(field)) {
            if (String(value).trim() === '') return;      // blank means unsaid, not zero
            v = Number(value);
        }
        try {
            await api(`/${SS.kind}s/${SS.id}`, { method: 'PUT', body: JSON.stringify({ [field]: v }) });
            SS.data[field] = v;
            if (el) el.style.borderColor = 'var(--gl-success, #166534)';
            setStatus('Saved');
        } catch (err) {
            if (el) el.style.borderColor = 'var(--gl-danger, #7f1d1d)';
            setStatus('Error: ' + err.message);
        }
    }

    async function addPropState() {
        const name = prompt('State name — clean, chipped, burnt?');
        if (!name || !name.trim()) return;
        const what = prompt('What is different about it?') || '';
        const scene = prompt('Which scene does it start in? (optional)') || '';
        let states = [];
        try { states = JSON.parse(SS.data.continuity_states || '[]') || []; } catch (_) { states = []; }
        states.push({ name: name.trim(), what: what.trim(), scene: scene.trim() });
        await savePropStates(states);
    }

    async function removePropState(i) {
        let states = [];
        try { states = JSON.parse(SS.data.continuity_states || '[]') || []; } catch (_) { states = []; }
        states.splice(i, 1);
        await savePropStates(states);
    }

    async function savePropStates(states) {
        try {
            await api(`/props/${SS.id}`, { method: 'PUT', body: JSON.stringify({ continuity_states: states }) });
            SS.data.continuity_states = JSON.stringify(states);
            await renderSubjectSheet();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /** The plate for whichever subject the sheet is open on. */
    function generateSheetPlate() {
        if (SS.kind === 'location') return generateLocationPlateFor(SS.id);
        return generatePropPlateFor(SS.id);
    }

    async function generateLocationPlateFor(id) {
        // Delegated: one gate, one preview, one set of controls.
        return regeneratePlate('location', id, null, () => {
            renderSubjectSheet();
            if (typeof loadLocations === 'function') loadLocations();
        });
    }

    async function generatePropPlateFor(id) {
        // Delegated: one gate, one preview, one set of controls.
        return regeneratePlate('prop', id, null, () => {
            renderSubjectSheet();
            if (typeof loadProps === 'function') loadProps();
        });
    }

    /**
     * Another view of the same place.
     *
     * A compass sweep and a time-of-day variant are the same operation with a
     * different view name — the location already stores views per name, and a
     * second mechanism for "the same place, different conditions" is how one of
     * them ends up not reaching gatherShotReferences.
     */
    /** From a subject sheet: sweep the compass, or photograph one named view. */
    async function generateLocationVariant(view) {
        if (view === 'compass') return sweepLocationCompass(SS.id);
        return regeneratePlate('location', SS.id, view, () => renderSubjectSheet());
    }

    /**
     * The gallery for whichever subject is open.
     *
     * Branched to literals rather than passing SS.kind through: the gallery
     * contract is checked by looking for the call per kind, and a computed
     * argument is invisible to it — a workspace nothing checks is one that
     * quietly loses its promote rule for one subject and not the others.
     */
    function openSubjectGallery() {
        if (!SS.id) return;
        const name = (SS.data && SS.data.name) || SS.kind;
        if (SS.kind === 'location') return openGallery('location', SS.id, name);
        return openGallery('prop', SS.id, name);
    }

    /**
     * The sheet as a printable document.
     *
     * Its own page rather than printing the app: the dark UI wastes a cartridge
     * and reads badly, which is why the screenplay export already does this.
     */
    function exportSubjectSheet() {
        if (!SS.data) return;
        const body = document.getElementById('ssBody');
        const w = window.open('', '_blank');
        if (!w) return setStatus('Allow pop-ups to export the sheet.');
        w.document.write(`<!doctype html><html><head><meta charset="utf-8">
            <title>${esc(SS.data.name || SS.kind)}</title>
            <style>
              @page { size: A4; margin: 16mm; }
              body { font-family: Georgia, 'Times New Roman', serif; color: #111; }
              h1 { font-size: 20pt; margin: 0 0 4mm; letter-spacing: .02em; }
              h4 { font-size: 9pt; letter-spacing: .08em; text-transform: uppercase;
                   color: #555; margin: 6mm 0 2mm; border-bottom: .3pt solid #bbb; padding-bottom: 1mm; }
              .ss-what { font-size: 8pt; color: #666; margin: 0 0 2mm; }
              img { max-width: 46mm; margin: 0 2mm 2mm 0; }
              .ss-grid { column-count: 2; column-gap: 10mm; }
              .ss-input, button, .btn-row, label > input, label > select { display: none !important; }
              .ss-region { break-inside: avoid; }
            </style></head><body>
            <h1>${esc(SS.data.name || '')}</h1>${body.innerHTML}</body></html>`);
        w.document.close();
        w.focus();
        setTimeout(() => w.print(), 400);
    }

    async function renderCharacterSheet() {
        const body = document.getElementById('csBody');
        try {
            const [ch, gal, pal] = await Promise.all([
                api(`/characters/${SHEET.id}`),
                api(`/characters/${SHEET.id}/gallery`).catch(() => ({ items: [] })),
                api(`/characters/${SHEET.id}/palette`).catch(() => ({ palette: [] })),
            ]);
            SHEET.character = ch.character || ch;
            SHEET.gallery = gal.items || [];
            SHEET.palette = pal.palette || [];
        } catch (err) {
            // A renderer that paints a placeholder must have a path that
            // replaces it, or a failure reads as the character being gone.
            body.innerHTML = `<div class="empty-state" style="padding:40px;"><h3>Could not load this character</h3>
                <p>${esc(err.message)}</p></div>`;
            return;
        }
        const c = SHEET.character;
        document.getElementById('csName').textContent = c.name || 'Character';

        const plates = csPlatesByView();
        const locked = CS_VIEWS.filter(v => plates[v.id]).length;
        document.getElementById('csChips').innerHTML = `
            <span class="cs-chip ${locked === 4 ? 'ok' : 'warn'}">Views ${locked}/4</span>
            ${c.gender || c.age_range
                ? `<span class="cs-chip">${esc([c.age_range, c.gender].filter(Boolean).join(' · '))}</span>` : ''}
            <span class="cs-chip">${SHEET.gallery.length} reference(s)</span>`;

        body.innerHTML = characterSheetHtml(c, plates);
    }

    /**
     * Which picture holds each official view.
     *
     * Legacy names are folded in: a `side` plate predates the left/right split
     * and would otherwise be ranked, on disk, and unreachable from this sheet —
     * money spent and nothing to show for it.
     */
    function csPlatesByView() {
        const out = {};
        for (const item of SHEET.gallery) {
            if (!item.sendable) continue;
            const v = CS_VIEWS.some(x => x.id === item.view) ? item.view : CS_LEGACY[item.view];
            if (v && !out[v]) out[v] = item;
        }
        return out;
    }

    function csImg(url) {
        return url && !/^https?:/i.test(url) ? API_BASE + url : url;
    }

    /*
     * A plate at the size it will be DRAWN, not the size it was made.
     *
     * Measured on the live install: the reference plates total 77MB, single
     * files run 668KB to 1.2MB, and a character card paints one at 48x48. The
     * first visit to an area pulled full plates down to make thumbnails of
     * them — loadCharacters took 863ms cold and 4ms warm, which is why the
     * slowness was intermittent and never reproduced on demand.
     *
     * file-storage.js has served a cached thumbnail for any `?w=` since it was
     * written, and falls through to the original on any failure so it can
     * never take down the picture it is optimising. Nothing had ever asked:
     * four thumbnails existed on the whole install, all under storyboards/.
     *
     * Built like frameSrc rather than as a second idiom, because the cache
     * buster and the width have to share one query string — a plate URL
     * already carries `?v=`.
     */
    function plateSrc(url, width) {
        const abs = csImg(url);
        if (!abs || !width) return abs;
        return abs + (abs.includes('?') ? '&' : '?') + 'w=' + width;
    }

    function characterSheetHtml(c, plates) {
        const spec = [
            ['Age', c.age_range], ['Gender', c.gender],
            ['Height', c.height_m ? c.height_m + ' m' : null], ['Build', c.build],
            ['Hair', c.hair], ['Distinguishing', c.distinguishing],
        ].filter(row => row[1]);

        const palette = csPalette();
        const refs = SHEET.gallery.filter(i => !i.sendable);
        const shown = SHEET.filter === 'all' ? refs
            : refs.filter(i => (i.metadata && i.metadata.ref_category) === SHEET.filter);

        return `
        <div class="cs-top">
          <div class="cs-col-l">
            <div class="cs-views-block">
              <div class="cs-label"><span>Official views</span><span class="rule"></span>
                <span class="note">canonical · fed to generation</span></div>
              <div class="cs-views">${CS_VIEWS.map(v => {
                  const p = plates[v.id];
                  return `<div class="cs-plate ${p ? 'locked' : 'pending'}"
                       onclick="${p ? `openPlateViewer(${jsAttr(csImg(p.image_url))}, ${jsAttr((c.name || '') + ' — ' + v.label)})`
                                    : `generateOfficialViews(${jsAttr(v.id)})`}">
                    ${p ? `<img src="${esc(plateSrc(p.image_url, 320))}" alt="">` : ''}
                    <span class="vlabel">${esc(v.label)}</span>
                    <span class="vcap">${p ? esc(v.caption) : 'generate →'}</span>
                    ${p ? '<span class="vdot"></span>'
                        : `<span class="cs-up" onclick="event.stopPropagation();">${
                            slotUpload('character', c.id, v.id, 'upload')}</span>`}
                  </div>`;
              }).join('')}</div>
            </div>

<div class="cs-physical">
              <div class="cs-label"><span>Physical spec</span><span class="rule"></span></div>
              ${spec.length
                  ? `<div class="cs-spec">${spec.map(([k, v]) =>
                        `<div class="cell"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`).join('')}</div>`
                  : `<p class="text-sm text-muted">Nothing recorded.
                       <a style="cursor:pointer;color:var(--gl-accent,#818cf8);"
                          onclick="closeModal('characterSheetModal'); editCharacter('${c.id}')">Add the physical spec</a>
                       — voice casting and the size in every prompt read these.</p>`}
            </div>

<div class="cs-palette">
              <div class="cs-label"><span>Palette</span><span class="rule"></span></div>
              ${palette.length
                  ? `<div class="cs-swatches">${palette.map((p, i) => `
                        <div class="cs-swatch" onclick="removePaletteSwatch(${i})"
                             title="Click to remove" style="cursor:pointer;">
                        <div class="chip" style="background:${esc(p.hex)};"></div>
                        <div class="cap">${esc(p.name || p.hex)}</div></div>`).join('')}</div>`
                  : '<p class="text-sm text-muted">No palette locked yet.</p>'}
              <div class="cs-add">
                <button class="btn btn-sm" onclick="addPaletteSwatch()">+ Colour</button>
                <button class="btn btn-sm" onclick="paletteFromImage()">From a picture</button>
              </div>
            </div>

<div class="cs-actions">
              <div class="cs-label"><span>Work on this character</span><span class="rule"></span></div>
              <div class="card-actions" style="flex-wrap:wrap;">
                <button class="btn btn-sm" onclick="generateCharacterImage('${c.id}')">Regen plate</button>
                <button class="btn btn-sm" onclick="orbitRefsheet('${c.id}')">Orbit sheet</button>
                <button class="btn btn-sm" onclick="showCharacterViews('${c.id}')">All views</button>
                <button class="btn btn-sm" onclick="openGallery('character', '${c.id}', ${jsAttr(c.name)})">Gallery</button>
                <button class="btn btn-sm" onclick="castCharacterVoice('${c.id}', ${jsAttr(c.name)})">Voice</button>
                ${uploadControl('character-plate', `/characters/${c.id}/refsheet/import`,
                    { extra: { view: 'front' }, after: 'renderCharacterSheet', title: 'Use a picture you already have' })}
              </div>
            </div>
          </div>

          <div class="cs-col-r">
            
            <div class="cs-details">
              <div class="cs-label"><span>Appearance</span>
                <span class="rule"></span>
                <span class="note">${(c.appearance_prompt || '').length} chars · prompt source</span></div>
              <div class="cs-prose">${esc(c.appearance_prompt || 'No appearance written. This is the text every plate is generated from.')}</div>
            </div>
            <!-- Side by side, as the reference sets them under one rule. Stacked
                 full width is what made this column run long and pushed the
                 reference strip below the fold. -->
            <div class="cs-two-up">
              <div>
                <div class="cs-label"><span>Description</span><span class="rule"></span></div>
                <div class="cs-prose small">${esc(c.description || '—')}</div>
              </div>
              <div>
                <div class="cs-label"><span>Personality</span><span class="rule"></span></div>
                <div class="cs-prose small">${esc(c.personality_notes || '—')}</div>
              </div>
            </div>

            <div class="cs-wardrobe">
              <div class="cs-label"><span>Wardrobe &amp; props</span><span class="rule"></span>
                <span class="note">continuity checklist</span></div>
              ${(() => {
                  // Wardrobe items ARE gallery pictures filed under `costume`,
                  // with the title as the note — one storage path and one
                  // upload flow, and the same picture the reference band shows.
                  const ward = SHEET.gallery.filter(i =>
                      (i.metadata && i.metadata.ref_category) === 'costume');
                  return ward.length
                      ? `<div class="cs-ward">${ward.map(w => `
                            <div class="item">
                              ${w.image_url
                                  ? `<img class="thumb" src="${esc(plateSrc(w.image_url, 320))}" alt=""
                                       onclick="openPlateViewer(${jsAttr(csImg(w.image_url))}, ${jsAttr(w.note || 'Wardrobe')})">`
                                  : '<div class="thumb"></div>'}
                              <div style="min-width:0;">
                                <div style="font-size:13px;color:#e8e8ea;">${esc(w.note || 'Wardrobe')}</div>
                                <div class="text-sm text-muted">${esc(w.role)}</div>
                              </div>
                            </div>`).join('')}</div>`
                      : '<p class="text-sm text-muted">No wardrobe recorded yet.</p>';
              })()}
              <div class="cs-add">
                <button class="btn btn-sm" onclick="addWardrobeItem()">+ Upload item</button>
                <button class="btn btn-sm" onclick="generateWardrobeItem()">Generate item</button>
              </div>
            </div>

            
          </div>
        </div>

        <div class="cs-refs">
          <div class="cs-label"><span>Concept art &amp; references</span>
            <div class="cs-pills">
              <span class="cs-pill ${SHEET.filter === 'all' ? 'active' : ''}"
                    onclick="csFilter('all')">All ${refs.length}</span>
              ${CS_CATEGORIES.map(cat => {
                  const n = refs.filter(i => (i.metadata && i.metadata.ref_category) === cat.id).length;
                  return `<span class="cs-pill ${SHEET.filter === cat.id ? 'active' : ''}"
                                onclick="csFilter('${cat.id}')">${esc(cat.label)} ${n}</span>`;
              }).join('')}
            </div>
            <span class="rule"></span>
            <span class="note">promoted refs are what conditions a frame</span></div>
          <div class="cs-tiles">
            ${shown.map(i => `
              <div class="cs-tile ${i.role === 'concept' ? '' : 'starred'}"
                   onclick="openPlateViewer(${jsAttr(csImg(i.image_url))}, ${jsAttr(c.name || '')})">
                ${i.image_url ? `<img src="${esc(plateSrc(i.image_url, 320))}" alt="">` : ''}
                <span class="tl">${esc((i.metadata && i.metadata.ref_category) || i.role)}${i.note ? ' · ' + esc(i.note) : ''}</span>
              </div>`).join('')}
            <div class="cs-tile cs-drop" onclick="addSheetReference()" title="A picture you already have">
              <div style="font-size:18px;">+</div><div>UPLOAD</div>
            </div>
            <div class="cs-tile cs-drop" onclick="generateSheetReference()" title="Generate one from a prompt — spends">
              <div style="font-size:18px;">✦</div><div>GENERATE</div>
            </div>
          </div>
        </div>`;
    }

    function csFilter(id) { SHEET.filter = id; renderCharacterSheet(); }

    /* ── putting things INTO the sheet ─────────────────────────────────────
     *
     * Three regions were read-only dead ends: the reference band could only be
     * filled from another modal, wardrobe said "no wardrobe recorded yet" with
     * no way to record any, and the palette pointed at a table with no UI. A
     * region that shows an empty state and offers no way out of it is a label.
     */

    /** Read a local file as a data URI. One reader for every upload here. */
    function csReadFile(accept) {
        return new Promise(resolve => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = accept || 'image/png,image/jpeg,image/webp';
            input.onchange = () => {
                const file = input.files && input.files[0];
                if (!file) { resolve(null); return; }
                const reader = new FileReader();
                reader.onload = () => resolve({ data: reader.result, name: file.name });
                reader.onerror = () => resolve(null);
                reader.readAsDataURL(file);
            };
            input.click();
        });
    }

    function csCategoryPrompt(label) {
        const ids = CS_CATEGORIES.map(c => c.id);
        const answer = prompt(`${label}\n\nCategory — ${ids.join(', ')}:`, 'sketch');
        if (answer === null) return undefined;              // cancelled
        const v = String(answer).trim().toLowerCase();
        return ids.includes(v) ? v : 'sketch';
    }

    /** A picture you already have, filed under a category. */
    async function addSheetReference() {
        const category = csCategoryPrompt('Add a reference you already have.');
        if (category === undefined) return;
        const file = await csReadFile();
        if (!file) return;
        const note = prompt('What is it? (optional)') || '';
        try {
            await api(`/characters/${SHEET.id}/inspiration`, {
                method: 'POST',
                body: JSON.stringify({ data: file.data, note, category }),
            });
            setStatus('Reference added.');
            await renderCharacterSheet();
        } catch (err) { setStatus('Could not add it: ' + err.message); }
    }

    /** A reference generated from a prompt, filed under a category. */
    /** One reference study, filed under a category. */
    async function generateSheetReference() {
        const category = csCategoryPrompt('Generate a reference.');
        if (category === undefined) return;
        const instruction = prompt('What should it show?\n\ne.g. "three-quarter face study, hard side light"');
        if (!instruction) return;
        return confirmPaidImage({
            title: 'Generate a reference',
            capability: 'image',
            previewUrl: `/characters/${SHEET.id}/explore/preview?count=1`
                + `&instruction=${encodeURIComponent(instruction)}`,
            note: 'Filed as a concept. It conditions nothing until it is promoted to a reference.',
            send: async choices => csBusy('Generating reference…', async () => {
                try {
                    await api(`/characters/${SHEET.id}/explore`, {
                        method: 'POST',
                        body: JSON.stringify({ ...choices, count: 1, instruction, category }),
                    });
                    if (typeof openCharacterSheet === 'function') await openCharacterSheet(SHEET.id);
                } catch (err) { setStatus('Error: ' + err.message); }
            }),
        });
    }

    /**
     * A wardrobe or prop item: a title and a picture.
     *
     * Stored as a gallery item filed under `costume` with the title as its
     * note, rather than in film_costumes — one storage path, one upload flow,
     * and the thumbnail is the same picture the reference band can show.
     */
    async function addWardrobeItem() {
        const title = prompt('Wardrobe or prop — what is it?\n\ne.g. "Rust cardigan / worn open, mid-hip"');
        if (!title) return;
        const file = await csReadFile();
        if (!file) return;
        try {
            await api(`/characters/${SHEET.id}/inspiration`, {
                method: 'POST',
                body: JSON.stringify({ data: file.data, note: title, category: 'costume' }),
            });
            setStatus('Wardrobe item added.');
            await renderCharacterSheet();
        } catch (err) { setStatus('Could not add it: ' + err.message); }
    }

    /** The same item, generated from its own description. */
    /** A wardrobe or prop study, filed under costume. */
    async function generateWardrobeItem() {
        const title = prompt('Wardrobe or prop — what is it?\n\ne.g. "Rust cardigan / worn open, mid-hip"');
        if (!title) return;
        return confirmPaidImage({
            title: `Generate "${title}"`,
            capability: 'image',
            previewUrl: `/characters/${SHEET.id}/explore/preview?count=1`
                + `&instruction=${encodeURIComponent(title)}`,
            note: 'Filed under costume as a concept.',
            send: async choices => csBusy('Generating wardrobe…', async () => {
                try {
                    await api(`/characters/${SHEET.id}/explore`, {
                        method: 'POST',
                        body: JSON.stringify({ ...choices, count: 1, instruction: title,
                            category: 'costume', note: title }),
                    });
                    if (typeof openCharacterSheet === 'function') await openCharacterSheet(SHEET.id);
                } catch (err) { setStatus('Error: ' + err.message); }
            }),
        });
    }

    /* ── the palette ───────────────────────────────────────────────────── */

    async function csSavePalette(palette) {
        const res = await api(`/characters/${SHEET.id}/palette`, {
            method: 'PUT', body: JSON.stringify({ palette }),
        });
        SHEET.palette = res.palette || [];
        if (res.note) setStatus(res.note);
        await renderCharacterSheet();
    }

    /** A colour typed in, with a name. */
    async function addPaletteSwatch() {
        const hex = prompt('Colour — #rrggbb', '#c4643a');
        if (!hex) return;
        const name = prompt('What is it? (optional)', '') || '';
        try {
            await csSavePalette([...(SHEET.palette || []), { hex, name }]);
        } catch (err) { setStatus('Could not save the palette: ' + err.message); }
    }

    async function removePaletteSwatch(index) {
        const next = (SHEET.palette || []).filter((_, i) => i !== index);
        try { await csSavePalette(next); }
        catch (err) { setStatus('Could not save the palette: ' + err.message); }
    }

    /**
     * Colours lifted from a picture already in the sheet.
     *
     * Sampled from the actual pixels on a canvas — a palette guessed from a
     * filename or a prompt would be a claim about the film that nothing
     * supports. Quantised coarsely and counted, so the answer is the colours
     * that COVER the image rather than the most saturated stray pixel.
     */
    async function paletteFromImage() {
        const usable = (SHEET.gallery || []).filter(i => i.image_url && !i.source_url);
        if (!usable.length) {
            setStatus('No picture in the sheet to sample — add a reference first.');
            return;
        }
        const which = usable.length === 1 ? usable[0] : usable[Math.max(0, Number(
            prompt('Sample which picture?\n\n' + usable.map((i, n) =>
                `${n + 1}. ${(i.metadata && i.metadata.ref_category) || i.role}`
                + (i.note ? ' — ' + i.note : '')).join('\n'), '1')) - 1)] || usable[0];

        await csBusy('Sampling colours…', () => new Promise(resolve => {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.onload = async () => {
                try {
                    const c = document.createElement('canvas');
                    const w = c.width = 80, h = c.height = Math.max(1, Math.round(80 * img.height / img.width));
                    const ctx = c.getContext('2d');
                    ctx.drawImage(img, 0, 0, w, h);
                    const px = ctx.getImageData(0, 0, w, h).data;
                    /*
                     * Coverage, but NOT the backdrop.
                     *
                     * Straight "most common colour" on a character plate
                     * returns five greys: a plate is shot on a seamless
                     * backdrop, so the thing that covers the image is the thing
                     * nobody wants in the palette. Near-neutral bins are set
                     * aside and only used if the picture has nothing else —
                     * a monochrome reference is a legitimate palette, and
                     * returning empty would look broken.
                     */
                    const bins = {}, neutral = {};
                    for (let i = 0; i < px.length; i += 4) {
                        if (px[i + 3] < 128) continue;
                        const r = px[i], g = px[i + 1], b = px[i + 2];
                        const max = Math.max(r, g, b), min = Math.min(r, g, b);
                        const key = [r, g, b].map(v => Math.round(v / 24) * 24).join(',');
                        // Chroma, not HSL saturation: a dark rust and a pale
                        // linen are both wanted, and lightness must not decide.
                        const target = (max - min) < 26 ? neutral : bins;
                        target[key] = (target[key] || 0) + 1;
                    }
                    const pick = Object.keys(bins).length >= 3 ? bins : neutral;
                    const top = Object.entries(pick).sort((a, b) => b[1] - a[1]).slice(0, 5)
                        .map(([k]) => {
                            const [r, g, b] = k.split(',').map(Number);
                            return { hex: '#' + [r, g, b].map(v =>
                                Math.min(255, v).toString(16).padStart(2, '0')).join(''), name: '' };
                        });
                    /*
                     * APPENDED, never replaced.
                     *
                     * Sampling is a suggestion; the swatches somebody typed are
                     * decisions. Overwriting them means one click destroys the
                     * palette they built, with no undo. Duplicates are dropped
                     * so sampling twice does not fill the row with one colour.
                     */
                    const have = new Set((SHEET.palette || []).map(x => x.hex));
                    const added = top.filter(x => !have.has(x.hex));
                    await csSavePalette([...(SHEET.palette || []), ...added]);
                    setStatus(added.length
                        ? `${added.length} colour(s) added from the picture.`
                        : 'Nothing new — those colours are already in the palette.');
                } catch (err) {
                    // A cross-origin image taints the canvas and getImageData
                    // throws. Said plainly rather than surfacing a SecurityError.
                    setStatus('That picture cannot be sampled (it is served from another origin).');
                }
                resolve();
            };
            img.onerror = () => { setStatus('Could not load that picture.'); resolve(); };
            img.src = csImg(which.image_url);
        }));
    }


    /**
     * The locked palette.
     *
     * On the CHARACTER. It used to read film_costumes.color_palette — a real
     * column on a table with no UI and zero rows, so the empty state advised a
     * surface that does not exist.
     */
    function csPalette() { return SHEET.palette || []; }

    /**
     * Generate the official views — all four, or one.
     *
     * Previewed and confirmed like every other paid button. A named view
     * generates only that one, which is what the pending plate's own click
     * does; with no argument it asks whether to do all four.
     */
    /**
     * Generate the official views — all four, or one.
     *
     * Each view goes through the SHARED confirmation, so the prompt is shown
     * and editable and the provider, model, quality and size can be chosen. It
     * used to be a bare confirm() naming a count, which told a director how
     * many images they were buying and nothing about what any of them would be.
     *
     * A sweep confirms ONCE and then runs, because four dialogs to buy a
     * turnaround is a worse experience than one; the choices made in that one
     * apply to every view in the sweep, which is what a turnaround wants
     * anyway — four views generated on different models is four different
     * people.
     */
    async function generateOfficialViews(view) {
        if (!SHEET.id) return;
        const c = SHEET.character || {};
        const wanted = view ? [view] : CS_VIEWS.map(v => v.id);
        const label = view ? (CS_VIEWS.find(v => v.id === view) || {}).label || view : 'all four views';

        return confirmPaidImage({
            title: `Generate ${label}`,
            capability: 'image',
            previewUrl: `/characters/${SHEET.id}/refsheet/preview${
                view ? `?view=${encodeURIComponent(view)}` : ''}`,
            note: `${wanted.length} image generation${wanted.length === 1 ? '' : 's'} for ${
                c.name || 'this character'}. Each replaces the current plate for its view, and `
                + 'every frame this character appears in is conditioned on one of them.',
            send: async choices => csBusy(`Generating ${wanted.length} view(s)…`, async () => {
                let made = 0;
                for (const v of wanted) {
                    try {
                        await api(`/characters/${SHEET.id}/refsheet/generate`, {
                            method: 'POST', body: JSON.stringify({ ...choices, views: [v] }),
                        });
                        made++;
                        setStatus(`Generated ${made} of ${wanted.length}…`);
                    } catch (err) {
                        // Stop on a refusal rather than asking again: a refusal
                        // repeated is a refusal paid for.
                        setStatus(`${made} of ${wanted.length} — then: ${err.message}`);
                        break;
                    }
                }
                if (made === wanted.length) setStatus(`${made} view(s) generated.`);
                if (typeof openCharacterSheet === 'function') await openCharacterSheet(SHEET.id);
            }),
        });
    }

    /**
     * Export the sheet as a printable page.
     *
     * Its own print document rather than the app's dark UI: printing a black
     * page wastes a cartridge and reads badly, which is the same reason the
     * screenplay export builds its own.
     */
    function exportCharacterSheet() {
        const c = SHEET.character;
        if (!c) return;
        const plates = csPlatesByView();
        const spec = [['Age', c.age_range], ['Gender', c.gender],
            ['Height', c.height_m ? c.height_m + ' m' : null], ['Build', c.build],
            ['Hair', c.hair], ['Distinguishing', c.distinguishing]].filter(r => r[1]);
        const ward = SHEET.gallery.filter(i => (i.metadata && i.metadata.ref_category) === 'costume');
        const palette = SHEET.palette || [];
        // Wardrobe has its own section, so it is not repeated in the contact
        // strip: the same picture twice on one page reads as a mistake.
        const refs = SHEET.gallery.filter(i => !i.sendable && i.image_url
            && (i.metadata && i.metadata.ref_category) !== 'costume');

        const win = window.open('', '_blank');
        if (!win) { setStatus('Allow pop-ups to export the sheet'); return; }
        win.document.write(`<!doctype html><html><head><meta charset="utf-8">
        <title>${esc(c.name || 'Character')} — character sheet</title>
        <style>
          @page { size: A4 portrait; margin: 20mm 18mm; }
          * { box-sizing: border-box; }
          body { font: 12px/1.55 Georgia, 'Times New Roman', serif; color:#111; background:#fff; margin:0; }
          h1 { font: 600 30px/1.1 Helvetica, Arial, sans-serif; letter-spacing:.14em;
               text-transform:uppercase; margin:0 0 2px; }
          .sub { font: 10px/1.4 ui-monospace, Menlo, monospace; letter-spacing:.16em;
                 text-transform:uppercase; color:#666; margin-bottom:16px; }
          .rule { border-top:2px solid #111; margin:0 0 18px; }
          h2 { font: 600 10px/1 ui-monospace, Menlo, monospace; letter-spacing:.2em;
               text-transform:uppercase; color:#666; margin:22px 0 8px;
               border-bottom:1px solid #ddd; padding-bottom:5px; }
          .views { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; }
          .views figure { margin:0; }
          .views img { width:100%; aspect-ratio:3/4; object-fit:cover; border:1px solid #ccc; }
          .views figcaption { font:9px ui-monospace,Menlo,monospace; letter-spacing:.12em;
              text-transform:uppercase; color:#666; margin-top:4px; }
          .spec { display:grid; grid-template-columns:repeat(3,1fr); gap:0; border:1px solid #ddd; }
          .spec div { padding:8px 10px; border-right:1px solid #eee; border-bottom:1px solid #eee; }
          .spec .k { font:9px ui-monospace,Menlo,monospace; letter-spacing:.16em;
              text-transform:uppercase; color:#888; }
          .spec .v { font-size:13px; margin-top:3px; }
          .prose { max-width:74ch; }
          .pal { display:flex; gap:10px; }
          .pal .sw { width:56px; height:40px; border:1px solid #bbb; border-radius:3px; }
          .pal .cap { font:9px ui-monospace,Menlo,monospace; color:#666; margin-top:4px;
              text-transform:uppercase; letter-spacing:.1em; }
          .pal .hex { color:#999; }
          .ward { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; }
          .ward figure { margin:0; }
          .ward img, .ward .blank { width:100%; aspect-ratio:3/4; object-fit:cover;
              border:1px solid #ccc; display:block; }
          .ward .blank { border-style:dashed; }
          .ward figcaption { font:9.5px ui-monospace,Menlo,monospace; color:#555; margin-top:4px; }
          .refs { display:grid; grid-template-columns:repeat(5,1fr); gap:6px; }
          .refs img { width:100%; aspect-ratio:4/3; object-fit:cover; border:1px solid #ddd; }
          .foot { margin-top:26px; padding-top:8px; border-top:1px solid #ddd;
              font:9px ui-monospace,Menlo,monospace; letter-spacing:.14em;
              text-transform:uppercase; color:#999; }
          @media print { .noprint { display:none; } }
        </style></head><body>
        <h1>${esc(c.name || 'Character')}</h1>
        <div class="sub">${esc([state.currentProject && state.currentProject.title,
            [c.age_range, c.gender].filter(Boolean).join(' · ')].filter(Boolean).join(' — '))}</div>
        <div class="rule"></div>
        <h2>Official views</h2>
        <div class="views">${CS_VIEWS.map(v => plates[v.id]
            ? `<figure><img src="${esc(plateSrc(plates[v.id].image_url, 320))}"><figcaption>${esc(v.label)}</figcaption></figure>`
            : `<figure><div style="aspect-ratio:3/4;border:1px dashed #bbb;"></div><figcaption>${esc(v.label)} — not generated</figcaption></figure>`).join('')}</div>
        ${spec.length ? `<h2>Physical spec</h2><div class="spec">${spec.map(([k, v]) =>
            `<div><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`).join('')}</div>` : ''}
        <h2>Appearance — prompt source</h2><div class="prose">${esc(c.appearance_prompt || '—')}</div>
        ${c.description ? `<h2>Description</h2><div class="prose">${esc(c.description)}</div>` : ''}
        ${c.personality_notes ? `<h2>Personality</h2><div class="prose">${esc(c.personality_notes)}</div>` : ''}
        ${palette.length ? `<h2>Palette</h2><div class="pal">${palette.map(p =>
            `<div><div class="sw" style="background:${esc(p.hex)}"></div>
             <div class="cap">${esc(p.name || '')}<br><span class="hex">${esc(p.hex)}</span></div></div>`).join('')}</div>` : ''}
        ${ward.length ? `<h2>Wardrobe &amp; props</h2><div class="ward">${ward.map(w =>
            `<figure>${w.image_url ? `<img src="${esc(plateSrc(w.image_url, 320))}">` : '<div class="blank"></div>'}
             <figcaption>${esc(w.note || 'Item')}</figcaption></figure>`).join('')}</div>` : ''}
        ${refs.length ? `<h2>Concept art &amp; references</h2><div class="refs">${refs.slice(0, 15).map(r =>
            `<img src="${esc(plateSrc(r.image_url, 320))}">`).join('')}</div>` : ''}
        <div class="foot">Film Engine · character sheet · ${esc(new Date().toISOString().slice(0, 10))}</div>
        <script>window.onload = function(){ setTimeout(function(){ window.print(); }, 400); };<\/script>
        </body></html>`);
        win.document.close();
        setStatus('Character sheet opened for printing');
    }

    /* ── casting a voice, and hearing a line ───────────────────────────────
     *
     * A PLANNING surface. Dialogue generation shipped in phase 4 reachable only
     * per SHOT — which means after a breakdown, which is after the point where
     * hearing a line would change what you write. And it would have been the
     * same voice every time: buildVoicePayload read a voice_id column that did
     * not exist, so every character fell through to the provider default.
     */
    let CASTING = { characterId: null, name: '', voices: [], selected: null };

    async function castCharacterVoice(characterId, name) {
        CASTING = { characterId, name: name || '', voices: [], selected: null };
        document.getElementById('castingTitle').textContent = `${name || 'Character'} — voice`;
        document.getElementById('auditionLine').value = '';
        document.getElementById('castingStatus').textContent = '';
        showModal('castingModal');
        await loadCastingBody();
    }

    async function loadCastingBody() {
        const body = document.getElementById('castingBody');
        body.innerHTML = '<div class="text-muted">Loading voices…</div>';
        let current;
        try {
            current = await api(`/characters/${CASTING.characterId}/voice`);
        } catch (err) {
            body.innerHTML = `<div class="empty-state"><h3>Could not load the catalogue</h3>
                <p>${esc(err.message)}</p></div>`;
            return;
        }

        const sg = current.suggestions;
        if (!sg || !sg.suggested.length) {
            body.innerHTML = `<div class="empty-state"><h3>No voices available</h3>
                <p>The provider returned no catalogue. Check the ElevenLabs credential in Setup.</p></div>`;
            return;
        }
        CASTING.voices = sg.suggested;
        CASTING.selected = CASTING.selected || current.voice_id || null;

        /*
         * What the sheet does not record is NAMED, with the way in.
         *
         * The engine already knows the character's gender and age; a flat list
         * of twenty-one voices makes the director re-derive that by ear. When a
         * field is missing the list is not narrowed — filtering on a guess is
         * worse — so the reason has to be visible, and the fix is one click.
         */
        /*
         * How this character always sounds.
         *
         * A cast voice is WHO they are; a delivery is HOW they speak. Set once
         * here, it is the baseline for every line, and a parenthetical on a
         * specific line overrides it — the same precedence the camera facets
         * follow. Changing it regenerates only that character's lines, because
         * the recording's hash covers the delivery.
         */
        const deliveryPicker = `
            <div class="gal-bar" style="margin-bottom:10px;">
                <label class="text-sm text-muted">Always sounds</label>
                <select id="castDelivery" onchange="setStandingDelivery()">
                    <option value="">— as written —</option>
                    ${(current.deliveries || []).map(d =>
                        `<option value="${esc(d.id)}" ${current.delivery === d.id ? 'selected' : ''}>${esc(d.id)} ${esc(d.tag)}</option>`).join('')}
                </select>
                <span class="text-muted text-sm">A parenthetical on a line still wins over this.</span>
            </div>`;

        const missingNote = sg.missing.length
            ? `<div class="warning-banner" style="margin-bottom:10px;">
                 ${esc(sg.note)}
                 <button class="btn btn-sm" style="margin-left:8px;"
                         onclick="closeModal('castingModal'); editCharacter('${CASTING.characterId}')">
                   Add ${esc(sg.missing.join(' and '))}
                 </button>
               </div>`
            : `<p class="text-sm text-muted" style="margin:0 0 10px;">Ordered for ${esc(sg.for || '')} —
                 ${esc([sg.matched_on.gender, sg.matched_on.age && String(sg.matched_on.age).replace('_', ' ')]
                     .filter(Boolean).join(', '))}.</p>`;

        body.innerHTML = missingNote + deliveryPicker + `
            <p class="text-sm" style="margin:0 0 10px;">
                ${current.cast
                    ? `Currently cast: <strong>${esc(current.voice_name || current.voice_id)}</strong>`
                    : `<span class="text-muted">${esc(current.warning || 'Not cast.')}</span>`}
            </p>
            ${sg.suggested.map(v => `
                <div class="voice-row ${v.voice_id === CASTING.selected ? 'is-cast' : ''}">
                    <span class="vname">${esc(v.name || v.voice_id)}</span>
                    <span class="vlabels">
                        ${esc([v.gender, v.age && String(v.age).replace('_', ' '), v.accent].filter(Boolean).join(' · ') || '—')}
                        ${v.why && v.why.length
                            ? `<span class="gal-badge reference" style="margin-left:6px;">matches ${esc(v.why.join(' + '))}</span>` : ''}
                        ${v.taken_by
                            ? `<span class="gal-badge inspiration" style="margin-left:6px;" title="Two characters in a scene sounding identical is usually a mistake — but doubling is a real choice, so this is flagged, not hidden">already ${esc(v.taken_by)}</span>` : ''}
                    </span>
                    ${v.preview_url
                        ? `<audio controls preload="none" src="${esc(v.preview_url)}"></audio>`
                        : '<span class="text-muted text-sm">no preview</span>'}
                    <button class="btn btn-sm ${v.voice_id === CASTING.selected ? '' : 'btn-primary'}"
                            onclick="pickVoice(${jsAttr(v.voice_id)}, ${jsAttr(v.name || '')})">
                        ${v.voice_id === CASTING.selected ? 'Cast' : 'Cast this'}
                    </button>
                </div>`).join('')}`;
    }

    /** Set (or clear) how this character always sounds. */
    async function setStandingDelivery() {
        const value = document.getElementById('castDelivery').value;
        const status = document.getElementById('castingStatus');
        status.textContent = 'Saving…';
        try {
            const cur = await api(`/characters/${CASTING.characterId}/voice`);
            if (!cur.voice_id) { status.textContent = 'Cast a voice first.'; return; }
            await api(`/characters/${CASTING.characterId}/voice`, {
                method: 'PUT',
                body: JSON.stringify({ voice_id: cur.voice_id, voice_name: cur.voice_name,
                    delivery: value || null }),
            });
            status.textContent = value
                ? `Always ${value}. Their lines will regenerate next time you press Dialogue.`
                : 'Delivery cleared.';
        } catch (err) { status.textContent = err.message; }
    }

    async function pickVoice(voiceId, voiceName) {
        const status = document.getElementById('castingStatus');
        status.textContent = 'Casting…';
        try {
            const res = await api(`/characters/${CASTING.characterId}/voice`, {
                method: 'PUT', body: JSON.stringify({ voice_id: voiceId, voice_name: voiceName }),
            });
            CASTING.selected = voiceId;
            status.textContent = res.changed ? (res.note || 'Cast.') : 'Already cast in this voice.';
            await loadCastingBody();
            loadCharacters();
        } catch (err) { status.textContent = err.message; }
    }

    /**
     * Hear a line. Attached to nothing.
     *
     * Previewed first and confirmed, like every other paid button — the preview
     * is free, so the gate costs nothing to pass and everything to skip.
     */
    async function auditionVoice() {
        const status = document.getElementById('castingStatus');
        const text = document.getElementById('auditionLine').value.trim();
        if (!text) { status.textContent = 'Type a line to hear.'; return; }

        status.textContent = 'Checking…';
        let pv;
        try {
            pv = await api(`/audition/preview?text=${encodeURIComponent(text)}`
                + (CASTING.selected ? `&voice_id=${encodeURIComponent(CASTING.selected)}` : '')
                + (CASTING.characterId ? `&character_id=${CASTING.characterId}` : ''));
        } catch (err) { status.textContent = 'Preview failed: ' + err.message; return; }
        if (pv.error) { status.textContent = pv.error; return; }

        if (!confirm(`Speak this line?\n\n"${text}"\n\nProvider: ${pv.provider}\n`
            + `Voice: ${pv.voice_id || 'the provider default'}\n`
            + `${pv.warning ? '\n' + pv.warning + '\n' : ''}\n`
            + 'This is an audition: it attaches to no shot.')) { status.textContent = ''; return; }

        status.textContent = 'Generating…';
        try {
            const res = await api('/audition', {
                method: 'POST',
                body: JSON.stringify({ text, voice_id: CASTING.selected,
                    character_id: CASTING.characterId,
                    project_id: state.currentProject && state.currentProject.id }),
            });
            status.textContent = 'Playing.';
            const body = document.getElementById('castingBody');
            const bar = document.createElement('div');
            bar.className = 'voice-row is-cast';
            bar.innerHTML = `<span class="vname">Audition</span>
                <span class="vlabels">${esc(text)}</span>
                <audio controls autoplay src="${esc(API_BASE + res.audio_url)}"></audio>`;
            body.prepend(bar);
        } catch (err) { status.textContent = 'Audition failed: ' + err.message; }
    }

    /* ── the table read ─────────────────────────────────────────────────── */

    /**
     * Hear a whole scene, before anything is shot.
     *
     * The question the shot-scoped route could not answer: how does this scene
     * PLAY. Free to read, paid to hear, and attached to no shot either way.
     */
    /**
     * Generate the dialogue for one scene's shots.
     *
     * The take the FILM uses: registered against each shot, and therefore what
     * playback, lip-sync and the mix all read. The old table read produced a
     * parallel set of audition files attached to nothing, which meant paying
     * twice for the same lines and throwing one set away.
     */
    /** Every shot in a scene, confirmed once and then run shot by shot. */
    async function generateSceneDialogue(sceneId, lineCount) {
        // Read the scene's shots here: nothing else on this page holds them,
        // and a lookup into an undefined global threw before anything showed.
        let shots = [];
        try {
            const r = await api(`/projects/${state.currentProject.id}/shotlist`);
            shots = ((r && (r.shots || r)) || []).filter(s => s.scene_id === sceneId);
        } catch (err) { setStatus('Could not read this scene\'s shots: ' + err.message, true); return; }
        if (!shots.length) { setStatus('This scene has no shots yet — break it down first.', true); return; }
        const first = shots[0];
        return confirmPaidImage({
            title: 'Generate the dialogue for this scene',
            capability: 'voice',
            previewUrl: first ? `/shots/${first.id}/voice/preview` : null,
            note: `${lineCount} line(s) across ${shots.length || 'the'} shot(s). The prompt shown `
                + 'is the first shot\'s; each shot is generated from its own lines, and the '
                + 'choices here apply to all of them.',
            editable: false,
            notEditableWhy: 'Each shot has its own lines — edit them on the shot card.',
            send: async choices => {
                let made = 0;
                for (const sh of shots) {
                    setStatus(`Generating ${sh.shot_code || ''}… (${made} of ${shots.length})`, true);
                    try {
                        await api(`/shots/${sh.id}/voice/generate`, {
                            method: 'POST', body: JSON.stringify(choices || {}),
                        });
                        made++;
                    } catch (err) {
                        // A provider that has started refusing will refuse the
                        // next one; stop rather than buying the same failure.
                        setStatus(`${made} of ${shots.length} — then: ${err.message}`);
                        return;
                    }
                }
                setStatus(`Dialogue generated for ${made} shot(s).`);
                if (typeof loadScenes === 'function') loadScenes();
            },
        });
    }

    /** What the read is doing, while it does it. */
    /* ── the takes that ship ────────────────────────────────────────────── */

    /**
     * A shot's dialogue, and the whole film's.
     *
     * These routes have existed since phase 4 with no control on any page —
     * generation reachable only from curl or an agent. Unlike an audition,
     * THIS one registers against the shot and is what lip-sync and the mix
     * consume, so the confirmation says which it is.
     */
    /** The take the film uses. Through the one gate, like everything that spends. */
    async function generateVoiceForShot(shotId, shotCode) {
        return confirmPaidImage({
            title: `Generate the dialogue for ${shotCode || 'this shot'}`,
            capability: 'voice',
            previewUrl: `/shots/${shotId}/voice/preview`,
            note: 'Unlike an audition this is registered against the shot — it is the take that '
                + 'lip-sync and the mix will use.',
            send: async choices => {
                setStatus('Generating dialogue…', true);
                try {
                    await api(`/shots/${shotId}/voice/generate`, {
                        method: 'POST', body: JSON.stringify(choices || {}),
                    });
                    setStatus('Dialogue generated.');
                    if (typeof loadScenes === 'function') loadScenes();
                } catch (err) { setStatus('Could not generate: ' + err.message); }
            },
        });
    }

    /* ── the subject workspace ─────────────────────────────────────────────
     *
     * One implementation for characters, locations and props. The three differ
     * only in which foreign key holds them, and three near-identical panels is
     * how one of them ends up with the promote rule and the others do not —
     * the fault lib/reference-plates.js was created to close for generation.
     */
    let GAL = { kind: null, id: null, name: '' };

    async function openGallery(kind, subjectId, name) {
        GAL = { kind, id: subjectId, name: name || '' };
        document.getElementById('galleryTitle').textContent = `${name || kind} — gallery`;
        document.getElementById('galInstruction').value = '';
        document.getElementById('galStatus').textContent = '';
        showModal('galleryModal');
        await loadGallery();
    }

    async function loadGallery() {
        const body = document.getElementById('galleryBody');
        body.innerHTML = '<div class="text-muted">Loading…</div>';
        let data;
        try {
            data = await api(`/${GAL.kind}s/${GAL.id}/gallery`);
        } catch (err) {
            // A renderer that paints a placeholder must have a path that
            // replaces it, or a failure reads as the pictures not existing.
            body.innerHTML = `<div class="empty-state"><h3>Could not load the gallery</h3>
                <p>${esc(err.message)}</p></div>`;
            return;
        }

        body.innerHTML = data.roles.map(role => {
            const items = data.by_role[role.id] || [];
            return `<div class="gal-group">
                <h4>${esc(role.title)} <span class="text-muted text-sm">(${items.length})</span></h4>
                <p class="gal-why">${esc(role.what)} ${esc(role.why)}</p>
                ${items.length
                    ? `<div class="gal-grid">${items.map(galCardHtml).join('')}</div>`
                    : `<p class="text-muted text-sm">${role.id === 'reference'
                        ? 'No approved reference. Every frame this subject appears in will invent it.'
                        : 'Nothing here yet.'}</p>`}
            </div>`;
        }).join('');
    }

    function galCardHtml(item) {
        const isRef = item.role === 'reference';
        /*
         * A served path is relative to the API, not to this page.
         *
         * The page is served from one port and the API from another, so a bare
         * `/film/refsheets/…` in an <img src> resolves against the PAGE and
         * 404s — a broken image icon where the approved plate should be, which
         * reads as the plate being lost. An absolute inspiration link is left
         * alone: it already names its own host.
         */
        const src = item.image_url && !/^https?:/i.test(item.image_url)
            ? API_BASE + item.image_url
            : item.image_url;
        // A link-only inspiration has no file to show; saying so beats a broken
        // image, which reads as the app losing the picture.
        const picture = item.image_url
            ? (/^https?:/.test(item.source_url || '')
                ? `<a class="gal-link" href="${esc(src)}" target="_blank" rel="noopener">${esc(src)}</a>`
                : `<img src="${esc(src)}" alt="" onclick="openPlateViewer(${jsAttr(src)}, ${jsAttr(GAL.name + (item.view ? ' — ' + item.view : ''))})">`)
            : '<div class="gal-link">no image</div>';

        return `<div class="gal-card ${isRef ? 'is-reference' : ''}">
            ${picture}
            <div class="gal-meta">
                <span class="gal-badge ${esc(item.role)}">${esc(item.role)}</span>
                ${item.view ? ` <span class="text-muted">${esc(item.view)}</span>` : ''}
                ${item.note ? `<div class="text-muted" style="margin-top:4px;">${esc(item.note)}</div>` : ''}
            </div>
            <div class="gal-actions">
                ${isRef
                    ? `<button class="btn btn-sm" onclick="setGalleryRole('${item.id}','concept')">Unset</button>`
                    : `<button class="btn btn-sm btn-primary" onclick="setGalleryRole('${item.id}','reference')">Make reference</button>`}
                <button class="btn btn-sm btn-danger" onclick="removeGalleryImage('${item.id}')">Delete</button>
            </div>
        </div>`;
    }

    async function setGalleryRole(assetId, role) {
        const status = document.getElementById('galStatus');
        status.textContent = 'Saving…';
        try {
            const res = await api(`/gallery/${assetId}/role`, {
                method: 'PUT', body: JSON.stringify({ role }),
            });
            status.textContent = res.changed ? (res.note || 'Saved') : (res.note || 'No change');
            if (res.warning) status.textContent = res.warning;
            await loadGallery();
        } catch (err) {
            /*
             * Promoting an inspiration is REFUSED rather than done quietly, and
             * the refusal is the place to offer the override — meeting a 409
             * with no way past is how a rule stops being read.
             */
            if (/inspiration/i.test(err.message)) {
                if (confirm(err.message + '\n\nMake it the reference anyway?')) {
                    await api(`/gallery/${assetId}/role`, {
                        method: 'PUT',
                        body: JSON.stringify({ role: 'reference', allow_inspiration: true }),
                    });
                    await loadGallery();
                    status.textContent = 'Promoted.';
                    return;
                }
                status.textContent = 'Left as inspiration.';
                return;
            }
            status.textContent = err.message;
        }
    }

    async function removeGalleryImage(assetId) {
        if (!confirm('Delete this picture?\n\nThe file is moved to a deleted/ folder rather than '
            + 'destroyed — a generated plate cost money.')) return;
        try {
            const res = await api(`/gallery/${assetId}`, { method: 'DELETE' });
            document.getElementById('galStatus').textContent = res.warning || 'Deleted.';
            await loadGallery();
        } catch (err) {
            document.getElementById('galStatus').textContent = err.message;
        }
    }

    /** Explore a subject: N concepts, through the one gate. */
    async function exploreSubject() {
        const count = Number(document.getElementById('galCount').value) || 3;
        const instruction = (document.getElementById('galInstruction').value || '').trim();
        const q = `count=${count}&instruction=${encodeURIComponent(instruction)}`;
        return confirmPaidImage({
            title: `Explore ${count} concept${count === 1 ? '' : 's'}`,
            capability: 'image',
            previewUrl: `/${GAL.kind}s/${GAL.id}/explore/preview?${q}`,
            note: 'Concepts are kept beside the subject and condition nothing until one is '
                + 'promoted to a reference.',
            send: async choices => {
                const status = document.getElementById('galStatus');
                if (status) status.textContent = 'Generating…';
                setStatus('Generating concepts…', true);
                try {
                    await api(`/${GAL.kind}s/${GAL.id}/explore`, {
                        method: 'POST', body: JSON.stringify({ ...choices, count, instruction }),
                    });
                    if (status) status.textContent = '';
                    setStatus('Concepts generated.');
                    await loadGallery();
                } catch (err) { if (status) status.textContent = 'Error: ' + err.message; }
            },
        });
    }

    function addInspirationPrompt() {
        const url = prompt('Paste an image link (http/https) — a still, a photograph, a reference:');
        if (!url) return;
        const note = prompt('What are you taking from it? (optional)') || '';
        api(`/${GAL.kind}s/${GAL.id}/inspiration`, {
            method: 'POST', body: JSON.stringify({ source_url: url, note }),
        }).then(async () => {
            document.getElementById('galStatus').textContent = 'Gathered as inspiration.';
            await loadGallery();
        }).catch(err => {
            document.getElementById('galStatus').textContent = err.message;
        });
    }

    function editCharacter(id) {
        const c = state.characters.find(x => x.id === id);
        if (!c) return;
        document.getElementById('characterModalTitle').textContent = 'Edit Character';
        document.getElementById('characterEditId').value = id;
        editingCharacterOriginalName = c.name || ''; // Store original name
        setModalData('characterModal', c);
        showModal('characterModal');
    }

    async function saveCharacter() {
        if (!state.currentProject) return;
        const editId = document.getElementById('characterEditId').value;
        const data = getModalData('characterModal');
        if (!data.name) return;

        // FILM-122: Check for name change and confirm screenplay propagation
        let propagateToScreenplay = true;
        if (editId && editingCharacterOriginalName && data.name !== editingCharacterOriginalName) {
            const confirmMsg = `Rename "${editingCharacterOriginalName}" to "${data.name}" in the screenplay too?\n\n` +
                'This will update all character cues in the screenplay.';
            propagateToScreenplay = confirm(confirmMsg);
            data.propagate_to_screenplay = propagateToScreenplay;
        }

        try {
            let response;
            if (editId) {
                response = await api('/characters/' + editId, { method: 'PUT', body: JSON.stringify(data) });
            } else {
                response = await api('/projects/' + state.currentProject.id + '/characters', { method: 'POST', body: JSON.stringify(data) });
            }

            // Show screenplay update info if applicable
            if (response.screenplay_update && response.screenplay_update.updated) {
                setStatus(`Character saved. Updated ${response.screenplay_update.occurrences} occurrence(s) in screenplay.`);
            } else {
                setStatus('Character saved');
            }

            closeModal('characterModal');
            clearModal('characterModal');
            document.getElementById('characterEditId').value = '';
            document.getElementById('characterModalTitle').textContent = 'New Character';
            editingCharacterOriginalName = '';
            loadCharacters();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteCharacter(id) {
        if (!confirm('Delete this character?')) return;
        try {
            await api('/characters/' + id, { method: 'DELETE' });
            loadCharacters();
            setStatus('Character deleted');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /**
     * The upload control that sits beside every Generate.
     *
     * "Everywhere I can generate plates or boards, I should be able to upload
     * one too, say I'm working outside of film engine."
     *
     * ONE builder rather than four literals, on the precedent markupToolbar()
     * set — the grid and the viewer came to disagree about their own tools
     * precisely because each wrote its own copy. Here the four places are
     * characters, locations, props and the mood board, and they must accept the
     * same formats and report the same way.
     */
    /*
     * Which capture device, if any, can fill a control that accepts THIS.
     *
     * Returns a `capture` value, '' for a medium that names no camera facing,
     * or null for an accept a camera cannot produce at all — a .tar.gz bundle,
     * a .glb, a screenplay. Deriving it here rather than at each call site is
     * the same rule uploadControl itself exists for: a caller that cannot
     * choose the attribute cannot get it wrong, and a control added later is
     * armed correctly with nothing to remember.
     *
     * NOTE the affordance is ADDITIVE. On iOS a file input carrying `capture`
     * goes straight to the camera and the Photo Library option disappears, so
     * arming the existing upload would have traded picking a render made
     * outside Film Engine — the common case — for shooting a new one. Both are
     * rendered instead.
     */
    /*
     * The second affordance: shoot one now. Rendered only where captureFor says
     * a camera or a microphone could actually fill the control, so a bundle or
     * screenplay importer never offers it. On a desktop browser the attribute
     * is simply ignored and the control behaves as another file picker, which
     * is why it is safe to render unconditionally on the media surfaces.
     */
    /* ── SHOOTING A PLATE ON THE PHONE ──────────────────────────────────────
     *
     * In a browser, Shoot is `<input type="file" capture="environment">` and
     * that is all a browser offers: one photograph per tap, with nothing on
     * screen saying which view you are on.
     *
     * In the iOS app a native bridge is available, and it is worth having for
     * exactly one reason — a turnaround is FOUR views, and the engine attaches
     * the front one to every frame the character appears in. Walking them
     * through a file input means four trips out to this page and back, hunting
     * for the next control each time.
     *
     * THE PAGE STILL DECIDES EVERYTHING. It sends the subject, the views and
     * the import route; native opens the camera and posts back to that same
     * route. Deciding in two places is the second surface the iOS design
     * exists to avoid.
     */
    const PLATE_CAMERA = 'plateCamera';

    function nativeCamera() {
        try {
            return (window.webkit && window.webkit.messageHandlers
                && window.webkit.messageHandlers[PLATE_CAMERA]) || null;
        } catch (_) { return null; }   /* a sandbox that throws on access is "no" */
    }

    /*
     * The views to walk for a target. A character is a turnaround; everything
     * else is one plate, and `default` is the view-less name the engine already
     * stores a subject's headline plate under.
     */
    function plateViewsFor(target) {
        if (target === 'character-plate') {
            return [
                { key: 'front',      label: 'Front' },
                { key: 'side-left',  label: 'Left side' },
                { key: 'side-right', label: 'Right side' },
                { key: 'back',       label: 'Back' },
            ];
        }
        return [{ key: '__default__', label: 'Plate' }];
    }

    let PLATE_CAMERA_AFTER = null;

    /** Ask the app to shoot. Returns immediately; the app calls back. */
    function shootPlate(target, url, subject, after) {
        const bridge = nativeCamera();
        if (!bridge) return;
        PLATE_CAMERA_AFTER = after || null;
        setStatus('Opening the camera\u2026');
        bridge.postMessage(JSON.stringify({
            url, apiBase: '', subject: subject || 'this subject',
            views: plateViewsFor(target),
            /*
             * WHERE it is going, so the camera budgets a take against the
             * ceiling that actually binds it. A walkthrough handed to Marble
             * gets 133 seconds at 1080p30 where the same mode shot for the cut
             * gets 200 — and a director who is shown the larger number
             * discovers the smaller one at upload, after the walk.
             */
            destination: captureDestination(target),
            /*
             * And what it may produce, so a footage session opens on the
             * transport rather than the shutter and its take is delivered.
             */
            media: captureMedia(target),
            /*
             * The delivery aspect, so the camera can guide the shape the plate
             * will actually be cropped to — a 9:16 deliverable guides 9:16.
             * previsAspect() is REUSED rather than the ratio parsed again here:
             * two readings of one project setting is how they come to disagree.
             */
            aspect: previsAspect(),
        }));
    }

    /*
     * The app's answer. NAMED PER VIEW rather than counted: "3 of 4 uploaded"
     * sends a director looking for which one is missing.
     */
    window.plateCameraDone = function (payload) {
        let r = {};
        try { r = JSON.parse(payload || '{}'); } catch (_) { r = {}; }
        const failed = Object.keys(r.failed || {});
        if (r.cancelled && !(r.uploaded || []).length) setStatus('Nothing was shot.');
        else if (failed.length) {
            setStatus(`Shot ${(r.uploaded || []).length}. Not uploaded: `
                + failed.map(k => `${k} (${r.failed[k]})`).join('; '));
        } else if ((r.uploaded || []).length) {
            setStatus(`${r.uploaded.join(', ')} shot and uploaded. Every shot referencing this `
                + 'subject uses them now.');
        }
        const after = PLATE_CAMERA_AFTER;
        PLATE_CAMERA_AFTER = null;
        if (after && typeof window[after] === 'function') window[after]();
    };

    /*
     * WHICH TARGETS THE CONTROLLED CAMERA FILLS.
     *
     * MIRRORED from backend/lib/media-imports.js, where the rule is stated once
     * and derived from the epic's own constraint — a target gets the camera if
     * what it holds is PHOTOGRAPHED IN THE WORLD. The page cannot require a node
     * module (build.target: single-html), so it exists twice and
     * fcc-system-camera.test.js holds the two equal element by element — the
     * same arrangement body-limit.js and screenplay-blocks.js already have, and
     * for the same reason: two rules that disagree is how a fix survives in the
     * tests and not on the screen.
     *
     * `video-media` is DELIBERATELY absent though footage is photographed. The
     * controlled camera records a take and nothing delivers it yet (FCC-014), so
     * that surface keeps the system camera, which does deliver a clip today.
     */
    /*
     * SELF-CONTAINED, deliberately. Four separate test harnesses lift the
     * control builders out of this page by extracting FUNCTIONS, and a helper
     * that reads a module-level constant hands them a ReferenceError — which
     * `nativeCamera()` then swallows in its own try/catch, so the harness is
     * told there is no bridge and every "in the app" assertion quietly measures
     * the browser arm instead. That happened while this was being written. A
     * helper the harnesses can run on its own cannot fail that way.
     */
    /*
     * WHERE a capture for this target is going, and therefore which ceiling
     * binds it. MIRRORED from backend/lib/media-imports.js — the page cannot
     * require a node module (build.target: single-html), so the rule exists
     * twice and fcc-previz-capture.test.js holds the two equal over every
     * target the registry declares.
     *
     * Self-contained for the reason `shootsWithCamera` is: four harnesses lift
     * these builders out by extracting FUNCTIONS, and a helper that reads a
     * module-level constant hands them a ReferenceError.
     *
     * `footage` is the default because it is what every target but one is, and
     * inventing `world` by accident would silently shorten every take by a
     * third — Marble caps a video at 100MB where the upload accepts 150.
     */
    function captureDestination(target) {
        return String(target || '') === 'world-capture' ? 'world' : 'footage';
    }

    function shootsWithCamera(target) {
        return [
            'storyboard-image', 'world-capture', 'character-plate', 'location-plate',
            'prop-plate', 'mood-board-image', 'continuity-ref', 'video-media',
        ].indexOf(String(target || '')) !== -1;
    }

    /*
     * WHICH MEDIA a session for this target may produce.
     *
     * `captureDestination` answers which CEILING binds; this answers what the
     * camera is being opened to MAKE, and they are two different questions. A
     * plate and a take share the destination `footage`, and a world capture
     * takes both a panorama and a walkthrough — so a session told only where it
     * is going opens the stills shutter for a clip and delivers nothing.
     *
     * MIRRORED from backend/lib/media-imports.js, self-contained for the reason
     * the two rules beside it are: four harnesses lift these builders out by
     * extracting FUNCTIONS, and a helper reading a module-level constant hands
     * them a ReferenceError that `nativeCamera` then swallows.
     *
     * A LiDAR scan is deliberately absent from the world capture's list: the
     * target accepts one, and this camera cannot make one.
     */
    function captureMedia(target) {
        const t = String(target || '');
        if (t === 'world-capture') return ['image', 'video'];
        if (t === 'video-media') return ['video'];
        return ['image'];
    }

    /*
     * THE ONE FUNCTION THAT DECIDES WHICH CAMERA A SURFACE OPENS.
     *
     * It used to render `<input capture>` and nothing else — the SYSTEM camera:
     * one photograph, no exposure or focus lock, no white balance held across a
     * turnaround, no level, no peaking, no zebras, no format and no budget. The
     * controlled camera nine tasks of this epic built was reachable only because
     * `uploadControl` wrote its own bridge branch, so the plates got it and the
     * world capture and every capability control silently did not.
     *
     * A branch written at a call site is a branch the next call site does not
     * get. That is the shape this codebase has paid for as `Regen` versus
     * `Generate All`, as the ambient bed that reached two surfaces of three, and
     * as AUDIO_LANES laying out four elements in one exporter and three in the
     * other. So the decision lives HERE, once, and a caller that cannot choose
     * cannot get it wrong.
     *
     * It is asked about a TARGET rather than an accept string because an accept
     * string cannot answer: a previs image and a location plate accept exactly
     * the same bytes, and one is rendered from a staged camera while the other
     * is a photograph of a real place.
     */
    function shootControl(target, url, accept, targetAttr, onchange, opts) {
        const o = opts || {};
        // The app's own camera, where there is one and this target photographs.
        if (shootsWithCamera(target) && nativeCamera()) return plateShootButton(target, url, o);

        /*
         * A browser has no better camera to offer, so it keeps the one it has.
         * Retiring the system camera means REPLACING it where a replacement
         * exists — deleting it everywhere would take the affordance off every
         * desktop and every phone browser.
         */
        const capture = captureFor(accept);
        if (capture === null) return '';
        const audio = capture === '';
        const label = o.shootLabel || (audio ? 'Record' : 'Shoot');
        const title = audio
            ? 'Record audio with this device'
            : 'Shoot it now with this device\u2019s camera';
        return `<label class="btn btn-secondary btn-sm" style="cursor:pointer;margin:0;"
                       title="${esc(title)}"
                       onclick="event.stopPropagation();">${esc(label)}
                    <input type="file" ${targetAttr}
                           accept="${accept}" capture="${capture}" style="display:none"
                           onclick="event.stopPropagation();"
                           onchange="${onchange}">
                </label>`;
    }

    /*
     * MIRRORED from backend/lib/body-limit.js. The page cannot require a node
     * module (build.target: single-html), so the rule exists twice and
     * upload-size-guard.test.js holds the two equal over real URLs — the same
     * arrangement screenplay-pagination.js already uses, and for the same
     * reason: two rules that disagree is how a fix survives in the tests and
     * not on the screen.
     */
    const UPLOAD_BODY_LIMITS = { json: 10 * 1048576, file: 150 * 1048576, bundle: 500 * 1048576, chunk: 16 * 1048576 };

    /** The BODY ceiling this URL is allowed, matching what the server enforces. */
    function uploadLimitFor(url) {
        const parts = String(url || '').split('?')[0].split('/').filter(Boolean);
        if (parts[0] === 'projects' && parts[1] === 'import') return UPLOAD_BODY_LIMITS.bundle;
        // One piece of a resumable upload: the server's CHUNK_LIMIT.
        if (parts[0] === 'uploads' && parts[1]) return UPLOAD_BODY_LIMITS.chunk;
        const last = parts[parts.length - 1];
        const carriesFile = parts.length > 1 && (last === 'import' || last === 'media' || last === 'stems');
        return carriesFile ? UPLOAD_BODY_LIMITS.file : UPLOAD_BODY_LIMITS.json;
    }

    /*
     * Refuse an oversize file HERE, before it is sent.
     *
     * The server answers 413 correctly, but reaching it means pushing the whole
     * file — on a phone, over mobile data — to be told no, and what comes back
     * reads as "Backend offline". Checking first turns a apparent outage into a
     * sentence naming the size and the limit.
     *
     * The file ceiling is three quarters of the body ceiling because uploads
     * travel base64-encoded, which is a third larger than the bytes.
     */
    function checkUploadSize(file, url) {
        if (!file || typeof file.size !== 'number') return;
        const bodyMax = uploadLimitFor(url);
        const fileMax = Math.floor(bodyMax * 3 / 4);
        if (file.size <= fileMax) return;
        const mb = (n) => `${(n / 1048576).toFixed(n < 10485760 ? 1 : 0)}MB`;
        throw new Error(`${file.name || 'That file'} is ${mb(file.size)}. The limit for this `
            + `upload is about ${mb(fileMax)} — uploads travel base64-encoded, which is a third `
            + 'larger than the file itself.');
    }

    function captureFor(accept) {
        const a = String(accept || '');
        if (/image\/|video\//.test(a)) return 'environment';   // rear camera
        if (/audio\//.test(a)) return '';                       // a mic has no facing
        return null;
    }

    /*
     * A WORLD CAPTURE is not a plate, so it does not go through uploadControl.
     *
     * uploadControl accepts PNG and JPEG because a plate is a picture. A
     * capture is whichever of three media the director stood in the room and
     * shot — a 360 panorama, a short orbit clip, or a LiDAR scan — and the
     * server decides which from the bytes, not from the name the phone gave it.
     * Offering all three from one control is what keeps that one act one act.
     *
     * The shoot affordance comes from the shared helper, so the accept type
     * decides the capture device exactly as it does everywhere else.
     */
    function captureUploadControl(locationId, opts) {
        const o = opts || {};
        const accept = 'image/png,image/jpeg,video/mp4,video/quicktime,.png,.jpg,.jpeg,.mp4,.mov,.glb';
        const url = `/locations/${locationId}/capture/import`;
        const onchange = `uploadReferenceImage(event, 'world-capture', '${url}', {}, '${o.after || ''}')`;
        return `<label class="btn btn-secondary btn-sm" style="cursor:pointer;margin:0;"
                       title="${esc(o.title || 'A panorama, a short orbit clip, or a LiDAR scan of the real place')}"
                       onclick="event.stopPropagation();">${esc(o.label || 'Add capture')}
                    <input type="file" data-import-target="world-capture"
                           accept="${accept}" style="display:none"
                           onclick="event.stopPropagation();"
                           onchange="${onchange}">
                </label>${shootControl('world-capture', url, accept,
                    'data-import-target="world-capture"', onchange, o)}`;
    }

    function uploadControl(target, url, opts) {
        const o = opts || {};
        return `<label class="btn btn-secondary btn-sm" style="cursor:pointer;margin:0;"
                       title="${esc(o.title || 'Use a picture you already have, made outside Film Engine')}"
                       onclick="event.stopPropagation();">${esc(o.label || 'Upload')}
                    <input type="file" data-import-target="${target}"
                           accept="image/png,image/jpeg,.png,.jpg,.jpeg" style="display:none"
                           onclick="event.stopPropagation();"
                           onchange="uploadReferenceImage(event, '${target}', '${url}', ${JSON.stringify(o.extra || {}).replace(/"/g, '&quot;')}, '${o.after || ''}')">
                </label>${shootControl(
                    target, url,
                    'image/png,image/jpeg,.png,.jpg,.jpeg',
                    `data-import-target="${target}"`,
                    `uploadReferenceImage(event, '${target}', '${url}', ${JSON.stringify(o.extra || {}).replace(/"/g, '&quot;')}, '${o.after || ''}')`,
                    o)}`;
    }

    /*
     * The native affordance, and it says what it will do. "Shoot" on a
     * character opens a four-view walk, not one photograph — a button that
     * takes longer than you expected is worse than one that said so.
     */
    function plateShootButton(target, url, o) {
        const views = plateViewsFor(target);
        const many = views.length > 1;
        const label = (o && o.shootLabel) || (many ? `Shoot ${views.length} views` : 'Shoot');
        const subject = (o && o.subject) || '';
        return `<button class="btn btn-secondary btn-sm" style="margin:0;"
                        title="${esc(many
                            ? 'Walk ' + views.map(v => v.label.toLowerCase()).join(', ') + ' in one pass'
                            : 'Shoot it now with this device\u2019s camera')}"
                        onclick="event.stopPropagation();shootPlate('${target}', '${url}', ${jsAttr(subject)}, '${o.after || ''}')">${esc(label)}</button>`;
    }

    /**
     * Send a picture the director already has, and put it where a generated one
     * would go.
     *
     * The refusal is rendered where the control is, not on the status bar — the
     * lesson the GLB importer paid for: a refusal one line high at the bottom of
     * the screen is indistinguishable from nothing having happened.
     */
    async function uploadReferenceImage(event, target, url, extra, after) {
        const file = event.target.files && event.target.files[0];
        if (!file) return;
        const label = event.target.closest('label');
        const original = label && label.firstChild && label.firstChild.textContent;
        if (label && label.firstChild) label.firstChild.textContent = 'Uploading… ';
        try {
            const data = await new Promise((resolve, reject) => {
                const r = new FileReader();
                r.onload = () => resolve(r.result);
                r.onerror = () => reject(new Error('That file could not be read.'));
                r.readAsDataURL(file);
            });
            checkUploadSize(file, url);
            const res = await api(url, {
                method: 'POST',
                body: JSON.stringify({ data, name: file.name, ...(extra || {}) }),
            });
            setStatus(`${file.name} uploaded. ${res.note || 'Every shot referencing this subject uses it now.'}`);
            if (after && typeof window[after] === 'function') window[after]();
            else if (typeof loadLocations === 'function' && target === 'location-plate') loadLocations();
        } catch (err) {
            // Named on the control, because the file input is cleared straight
            // after and there would otherwise be no trace it was ever tried.
            setStatus(`${file.name} was not uploaded: ${err.message}`);
            if (label) {
                label.style.borderColor = 'var(--gl-danger,#ef4444)';
                label.title = 'Not uploaded: ' + err.message;
                setTimeout(() => { label.style.borderColor = ''; }, 6000);
            }
        } finally {
            if (label && label.firstChild && original) label.firstChild.textContent = original;
            event.target.value = '';
        }
    }

    /**
     * Upload footage or sound made outside Film Engine.
     *
     * Same shape as uploadControl() and deliberately a separate builder,
     * because these differ in the two things that matter: what the picker will
     * let you select, and whether the file belongs to a SHOT or a SCENE. A
     * music bed posted at a shot would attach a whole scene's score to one shot
     * and read as working; the server refuses it, and the control never offers
     * it in the first place.
     */
    function mediaUploadControl(capability, media, scope, ownerId, opts) {
        const o = opts || {};
        const accept = media === 'video'
            ? 'video/mp4,video/quicktime,video/webm,video/x-matroska,.mp4,.mov,.webm,.mkv'
            : 'audio/wav,audio/mpeg,audio/mp4,audio/flac,audio/ogg,.wav,.mp3,.m4a,.flac,.ogg';
        /*
         * A sequence has its own import route rather than sharing the shot one:
         * a clip dropped on a sequence must also mark that sequence complete
         * and point at the file, or the page still shows it as never run.
         */
        // A cue's audio has its own route: it must LINK the file to the cue, not
        // merely land it on the scene. An asset carries no level, no fades and
        // no place on the sheet, so an upload that stops at the scene is a file
        // nobody hears.
        const url = scope === 'cue'
            ? `/music-cues/${ownerId}/audio`
            : scope === 'sequence'
                ? `/sequences/${ownerId}/import`
                : `/${scope === 'scene' ? 'scenes' : 'shots'}/${ownerId}/media/${capability}/import`;
        return `<label class="btn btn-secondary btn-sm" style="cursor:pointer;margin:0;"
                       title="${esc(o.title || `Use ${media === 'video' ? 'a clip' : 'audio'} you made elsewhere — it is stored exactly where a generated one goes`)}"
                       onclick="event.stopPropagation();">${esc(o.label || 'Upload')}
                    <input type="file" data-import-target="${capability}-media"
                           accept="${accept}" style="display:none"
                           onclick="event.stopPropagation();"
                           onchange="uploadCapabilityMedia(event, '${capability}', '${url}', '${o.after || ''}', '${scope === 'shot' ? ownerId : ''}')">
                </label>${shootControl(
                    `${capability}-media`, url, accept,
                    `data-import-target="${capability}-media"`,
                    `uploadCapabilityMedia(event, '${capability}', '${url}', '${o.after || ''}', '${scope === 'shot' ? ownerId : ''}')`,
                    o)}`;
    }

    /** Send it, and say plainly where it landed and what is still unresolved. */
    /**
     * Say which shots one clip contains, on the card, after it is uploaded.
     *
     * This replaced a native prompt() asked BEFORE the upload, where cancelling
     * abandoned the clip with nothing said. Here nothing is at stake: the file
     * is already stored, and answering or not answering only changes how it
     * plays back.
     *
     * Only the shots that consecutively FOLLOW are offered, because that is the
     * only shape a clip can have and the server refuses the rest — a picker
     * offering what the server rejects is how a picker stops being believed.
     */
    async function setClipCoverage(shotId, btn) {
        const shots = state.videoShots || [];
        const at = shots.findIndex(s => s.id === shotId);
        if (at < 0) return;
        const here = shots[at];
        const following = shots.slice(at + 1);
        if (!following.length) {
            return setStatus(`${here.shot_code} is the last shot — there is nothing after it for a clip to cover.`);
        }

        const media = (state.videoAssetsByShot || {})[shotId] || {};
        const asset = media.video_raw || media.video_final || media.video_synced;
        if (!asset || !asset.id) return setStatus('This shot has no clip to describe yet.');

        const answer = await pickCoverageRun(here, following);
        if (answer === null) return;                       // closed it: nothing happens

        if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
        try {
            const ids = [shotId, ...following.slice(0, answer).map(s => s.id)];
            const res = await api(`/assets/${asset.id}/coverage`, {
                method: 'PUT', body: JSON.stringify({ shot_ids: answer ? ids : [] }),
            });
            setStatus(res.note || 'Coverage saved.');
            loadVideoShots();
        } catch (err) {
            setStatus('Could not set the coverage: ' + err.message);
        } finally {
            if (btn) { btn.disabled = false; btn.textContent = 'Covers…'; }
        }
    }

    /** A small in-page chooser. Returns how many following shots, 0 to clear, or null. */
    function pickCoverageRun(here, following) {
        return new Promise(resolve => {
            const box = document.createElement('div');
            box.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9998;'
                + 'display:flex;align-items:center;justify-content:center;';
            const done = v => { box.remove(); resolve(v); };
            box.innerHTML = `<div class="card" style="max-width:460px;">
                <h3 style="margin:0 0 8px;">What does this clip contain?</h3>
                <p class="text-sm text-muted" style="margin:0 0 12px;line-height:1.5;">
                    If one video covers several shots, the shots inside it stop playing their own
                    storyboard frames and stop being reported as missing footage.
                </p>
                <div id="covChoices" style="display:flex;flex-direction:column;gap:6px;"></div>
            </div>`;
            const list = box.querySelector('#covChoices');
            const add = (label, value) => {
                const b = document.createElement('button');
                b.className = 'btn btn-secondary btn-sm';
                b.style.textAlign = 'left';
                b.textContent = label;
                b.onclick = () => done(value);
                list.appendChild(b);
            };
            add(`Just ${here.shot_code}`, 0);
            following.forEach((s, i) => add(`${here.shot_code} through ${s.shot_code}`, i + 1));
            const cancel = document.createElement('button');
            cancel.className = 'btn btn-secondary btn-sm';
            cancel.textContent = 'Cancel';
            cancel.style.marginTop = '6px';
            cancel.onclick = () => done(null);
            list.appendChild(cancel);
            // Closing it changes nothing — the clip is already uploaded.
            box.addEventListener('click', e => { if (e.target === box) done(null); });
            document.body.appendChild(box);
        });
    }

    async function uploadCapabilityMedia(event, capability, url, after, shotId) {
        const file = event.target.files && event.target.files[0];
        if (!file) return;

        /*
         * NOTHING STANDS BETWEEN THE FILE AND THE UPLOAD.
         *
         * This used to ask, with a native prompt(), whether the clip contained
         * more than one shot — before sending anything. Cancelling that dialog
         * abandoned the upload with nothing said, so pressing Escape on an
         * unexpected question silently discarded the clip and the symptom was
         * "playback doesn't include the video" for a file that had never
         * reached the server. A native modal also cannot be seen in a
         * screenshot, so the page merely appeared to have stopped.
         *
         * The question is asked afterwards, on the shot card, where the answer
         * is better informed anyway: a director who has watched the clip back
         * knows what is in it.
         */
        const label = event.target.closest('label');
        const original = label && label.firstChild && label.firstChild.textContent;
        /*
         * Media files are large and the read alone is slow, so the control has
         * to say it is working. A silent 40-second upload is indistinguishable
         * from a dead button, which is how the GLB import came to be reported
         * as broken when it was not.
         */
        if (label && label.firstChild) label.firstChild.textContent = 'Uploading… ';
        setStatus(`Uploading ${file.name} (${(file.size / 1048576).toFixed(1)}MB)…`, true);
        try {
            // Was a second copy of the ceiling, hardcoded at 112MB. One rule,
            // mirrored from the server and held equal to it by test.
            checkUploadSize(file, url);
            const data = await new Promise((resolve, reject) => {
                const r = new FileReader();
                r.onload = () => resolve(r.result);
                r.onerror = () => reject(new Error('That file could not be read.'));
                r.readAsDataURL(file);
            });
            const res = await api(url, {
                method: 'POST',
                body: JSON.stringify({ data, name: file.name }),
            });
            /*
             * A refused coverage is reported ON ITS OWN. The upload succeeded
             * and the file is on its shot; saying "uploaded" alone would let a
             * director believe 1B and 1C are inside it when they still play
             * their own frames.
             */
            setStatus(`${file.name} uploaded as ${res.asset_type}`
                + (res.duration_ms ? ` (${(res.duration_ms / 1000).toFixed(1)}s)` : '')
                + '. It plays in Playback now.'
                + (capability === 'video' && shotId
                    ? ' If this one clip covers several shots, say so with “Covers…” on the card.' : ''));
            if (capability === 'video' && shotId) window.__lastUploadedClip = res.asset_id;
            if (after && typeof window[after] === 'function') window[after]();
        } catch (err) {
            setStatus(`${file.name} was not uploaded: ${err.message}`);
            if (label) {
                label.style.borderColor = 'var(--gl-danger,#ef4444)';
                label.title = 'Not uploaded: ' + err.message;
                setTimeout(() => { label.style.borderColor = ''; }, 8000);
            }
        } finally {
            if (label && label.firstChild && original) label.firstChild.textContent = original;
            event.target.value = '';
        }
    }

    /*
     * A turnaround from ONE orbit rather than three separate generations.
     *
     * Three plates are three independent rolls of the dice and can disagree
     * about the face, the wardrobe and the build; frames of one continuous
     * motion cannot. It is also cheaper — about 25 credits against 45.
     *
     * Goes through the same pre-spend confirmation as every other paid button,
     * built from the FREE preview, so the number under the button is the number
     * that will be charged.
     */
    /* ── Keep the actor, change the background ───────────────────────────
     *
     * The one control here that EDITS footage instead of making some. It is
     * two steps on purpose: the instruction is asked for first, then the
     * shared gate shows the assembled prompt and the real cost — because the
     * price depends on the clip's measured LENGTH, so a confirmation raised
     * before the source is known would show a number that is not the one
     * charged.
     */
    function askBackgroundInstruction() {
        return new Promise(resolve => {
            const id = 'bgInstructionModal';
            showModalHtml(id, `
                <h3 style="margin-top:0;">Replace the background</h3>
                <p class="text-sm text-muted" style="line-height:1.5;">
                  Describe the PLACE and nothing else. The people, their positions and the camera
                  are preserved by the model — describing them again is what makes it re-render them.
                </p>
                <div class="form-group">
                  <label>The new background</label>
                  <textarea id="bgInstructionText" rows="3"
                    placeholder="a rain-soaked street at night, sodium streetlights, wet asphalt"></textarea>
                </div>
                <div class="flex-between" style="margin-top:12px;">
                  <button class="btn btn-secondary btn-sm" onclick="bgInstructionDone(null)">Cancel</button>
                  <button class="btn btn-primary btn-sm" onclick="bgInstructionDone()">See what it would cost</button>
                </div>`);
            BG_INSTRUCTION = resolve;
            const box = document.getElementById('bgInstructionText');
            if (box) box.focus();
        });
    }
    let BG_INSTRUCTION = null;
    function bgInstructionDone(force) {
        const box = document.getElementById('bgInstructionText');
        const value = force === null ? null : ((box && box.value) || '').trim();
        closeModal('bgInstructionModal');
        const done = BG_INSTRUCTION; BG_INSTRUCTION = null;
        if (done) done(value);
    }

    async function replaceBackground(shotId, btn) {
        const instruction = await askBackgroundInstruction();
        if (!instruction) return;   // cancelled, or nothing said
        return confirmPaidImage({
            capability: 'video',
            title: 'Replace the background',
            note: 'The performance in this clip is kept and re-rendered somewhere else. Runway '
                + 'bills this by the length of the clip handed IN, not the length asked for, so a '
                + 'longer take costs more for the same edit. The result lands as a NEW version — '
                + 'the take being edited survives.',
            previewUrl: `/shots/${shotId}/video/background/preview?instruction=`
                + encodeURIComponent(instruction),
            editable: false,
            notEditableWhy: 'The clause that holds the actor still is not editable — deleting it is '
                + 'what makes the model re-render the performance. Change the background above.',
            send: async () => {
                setStatus('Replacing the background…', true);
                if (btn) { btn.disabled = true; btn.dataset.was = btn.textContent; btn.textContent = 'Replacing…'; }
                try {
                    const res = await api(`/shots/${shotId}/video/background/generate`,
                        { method: 'POST', body: JSON.stringify({ instruction }) });
                    setStatus(res && res.ok
                        ? `Background replaced — v${res.version} on this shot. The previous take is still there.`
                        : `Could not replace the background (${(res && res.stage) || 'unknown'} stage): `
                          + ((res && res.reason) || 'no reason given'));
                    if (typeof loadVideoShots === 'function') loadVideoShots();
                } catch (err) {
                    setStatus('Could not replace the background: ' + err.message);
                } finally {
                    // A spinner still turning after a failure is worse than
                    // none: it says work is happening when nothing is.
                    if (btn) { btn.disabled = false; if (btn.dataset.was) btn.textContent = btn.dataset.was; }
                }
            },
        });
    }

    async function orbitRefsheet(characterId) {
        return confirmPaidImage({
            capability: 'video',
            title: 'Turnaround from one orbit',
            note: 'Generates a short clip that orbits the character, then cuts it into front, '
                + 'three-quarter, side and back. The views come from one motion, so they cannot '
                + 'disagree with each other the way three separate plates can.',
            previewUrl: `/characters/${characterId}/refsheet/orbit/preview`,
            editable: false,
            notEditableWhy: 'The orbit prompt is composed from the character description and the '
                + 'film\'s medium. Edit the character, then preview again.',
            send: async () => {
                setStatus('Generating orbit turnaround…', true);
                try {
                    const res = await api(`/characters/${characterId}/refsheet/orbit`,
                        { method: 'POST', body: JSON.stringify({}) });
                    const n = (res && res.views ? res.views.length : 0);
                    setStatus(n ? `Turnaround cut: ${res.views.map(v => v.view).join(', ')}`
                        : (res && res.error) || 'The orbit produced no frames.');
                    if (typeof loadCharacters === 'function') loadCharacters();
                } catch (err) { setStatus('Could not generate the orbit: ' + err.message); }
            },
        });
    }

    async function generateCharacterImage(charId) {
        /*
         * The prompt this plate is generated from, before it is bought. A plate
         * conditions EVERY frame its subject appears in, so it is the single
         * worst request to send unread — and it is editable, because the
         * commonest fix is a word in the appearance rather than a re-roll.
         */
        return confirmPaidImage({
            capability: 'image',
            title: 'Generate character plate',
            note: 'This picture becomes the reference for every frame this character appears in.',
            previewUrl: `/characters/${charId}/refsheet/preview?views=front`,
            send: async choices => {
                setStatus('Generating character reference image...', true);
                try {
                    await api('/characters/' + charId + '/refsheet/generate', {
                        method: 'POST', body: JSON.stringify({ views: ['front'], ...choices }),
                    });
                    setStatus('Character image generated');
                    loadCharacters();
                } catch (err) { setStatus('Error generating image: ' + err.message); }
            },
        });
    }

    // ══════════════════════════════════════════════════════════════
    // LOCATIONS
    // ══════════════════════════════════════════════════════════════
    async function loadLocations() {
        if (!state.currentProject) return;
        try {
            const data = await api('/projects/' + state.currentProject.id + '/locations');
            state.locations = data.locations || [];
            const el = document.getElementById('locationGrid');
            if (state.locations.length === 0) {
                el.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><div class="icon">&#128205;</div><h3>No locations</h3><p>Add filming locations.</p></div>`;
            } else {
                el.innerHTML = state.locations.map(l => `
                    <div class="entity-card" style="cursor:pointer;" onclick="openSubjectSheet('location', '${l.id}')" title="Open the location sheet">
                        ${l.reference_image_url
                            ? '<img src="' + plateSrc(l.reference_image_url, 480) + '" style="width:calc(100% + 24px);height:120px;object-fit:cover;border-radius:8px 8px 0 0;margin:-12px -12px 8px -12px;cursor:zoom-in;" title="Click to see the plate full size"'
                                + ' onclick="event.stopPropagation(); openPlateViewer(\'' + API_BASE + l.reference_image_url + '\', ' + jsAttr(l.name) + ')"'
                                + ' onerror="this.style.display=\'none\'">'
                            : ''}
                        <div class="entity-card-header">
                            <div class="entity-avatar" style="border-radius:8px;">&#128205;</div>
                            <div>
                                <h3>${esc(l.name)}</h3>
                                <p class="text-sm text-muted">${l.scene_count || 0} scene(s)</p>
                            </div>
                        </div>
                        <p>${esc(l.description || 'No description')}</p>
                        <div class="tag-row">
                            ${l.lighting_default ? '<span class="tag">' + esc(l.lighting_default) + '</span>' : ''}
                            ${l.time_of_day_default ? '<span class="tag">' + esc(l.time_of_day_default) + '</span>' : ''}
                        </div>
                        <div class="card-actions">
                            <!--
                              Two buttons. Everything else moved onto the sheet,
                              where there is room to work — see RELOCATED in
                              lib/subject-sheets.js, which holds each moved
                              action to still having a home.
                            -->
                            <button class="btn btn-secondary btn-sm" onclick="event.stopPropagation(); editLocation('${l.id}')">Edit</button>
                            <button class="btn btn-danger btn-sm" onclick="event.stopPropagation(); deleteLocation('${l.id}')">Delete</button>
                        </div>
                    </div>`).join('');
            }
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function editLocation(id) {
        const l = state.locations.find(x => x.id === id);
        if (!l) return;
        document.getElementById('locationModalTitle').textContent = 'Edit Location';
        document.getElementById('locationEditId').value = id;
        editingLocationOriginalName = l.name || ''; // FILM-122: Store original name
        setModalData('locationModal', l);
        showModal('locationModal');
    }

    async function saveLocation() {
        if (!state.currentProject) return;
        const editId = document.getElementById('locationEditId').value;
        const data = getModalData('locationModal');
        if (!data.name) return;

        // FILM-122: Check for name change and confirm screenplay propagation
        let propagateToScreenplay = true;
        if (editId && editingLocationOriginalName && data.name !== editingLocationOriginalName) {
            const confirmMsg = `Rename "${editingLocationOriginalName}" to "${data.name}" in the screenplay too?\n\n` +
                'This will update all scene headings in the screenplay.';
            propagateToScreenplay = confirm(confirmMsg);
            data.propagate_to_screenplay = propagateToScreenplay;
        }

        try {
            let result;
            if (editId) {
                result = await api('/locations/' + editId, { method: 'PUT', body: JSON.stringify(data) });
            } else {
                result = await api('/projects/' + state.currentProject.id + '/locations', { method: 'POST', body: JSON.stringify(data) });
            }
            closeModal('locationModal');
            clearModal('locationModal');
            document.getElementById('locationEditId').value = '';
            document.getElementById('locationModalTitle').textContent = 'New Location';
            editingLocationOriginalName = '';
            loadLocations();

            // FILM-122: Show screenplay update status
            if (result && result.screenplay_update) {
                const su = result.screenplay_update;
                if (su.updated) {
                    setStatus(`Location saved. Screenplay updated: ${su.occurrences} occurrence(s) renamed (v${su.new_version})`);
                    // Reload the screenplay so the rename is visible. Named
                    // loadScreenplayPage: the old call was `loadScreenplay`,
                    // which nothing defines, so a save that WORKED reported
                    // "Error: loadScreenplay is not defined" from the catch.
                    loadScreenplayPage();
                } else {
                    setStatus(`Location saved. Screenplay: ${su.reason || 'no changes needed'}`);
                }
            } else {
                setStatus('Location saved');
            }
        } catch (err) { setStatus('Error: ' + err.message); }
    }

