    function renderGlossary(filter = '') {
        const container = document.getElementById('glossaryContent');
        const query = filter.toLowerCase().trim();
        let html = '';
        let totalMatches = 0;

        for (const [category, terms] of Object.entries(GLOSSARY)) {
            const sortedTerms = Object.entries(terms).sort((a, b) => a[0].localeCompare(b[0]));
            const filtered = query
                ? sortedTerms.filter(([name, def]) =>
                    name.toLowerCase().includes(query) || def.toLowerCase().includes(query))
                : sortedTerms;

            if (filtered.length === 0) continue;
            totalMatches += filtered.length;

            html += `<div class="glossary-category">`;
            html += `<div class="glossary-category-title">${category}</div>`;
            for (const [name, def] of filtered) {
                const highlightedName = query
                    ? name.replace(new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi'), '<mark>$1</mark>')
                    : name;
                const highlightedDef = query
                    ? def.replace(new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi'), '<mark>$1</mark>')
                    : def;
                html += `<div class="glossary-term">
                    <div class="glossary-term-name">${highlightedName}</div>
                    <div class="glossary-term-def">${highlightedDef}</div>
                </div>`;
            }
            html += `</div>`;
        }

        if (totalMatches === 0) {
            html = `<div class="glossary-empty">No terms matching "${filter}"</div>`;
        }

        container.innerHTML = html;
    }

    function filterGlossary() {
        const val = document.getElementById('glossarySearch').value;
        renderGlossary(val);
    }

